/* ============================ TITLE ============================ */
.screen { position: absolute; inset: 0; z-index: 10; }
#startScreen {
  display: flex; flex-direction: column; justify-content: center;
  padding: max(24px, env(safe-area-inset-top)) clamp(22px, 6vw, 96px) max(22px, env(safe-area-inset-bottom));
  background:
    linear-gradient(90deg, rgba(3, 4, 9, 0.92) 0%, rgba(3, 4, 9, 0.7) 34%, rgba(3, 4, 9, 0.12) 62%, rgba(3, 4, 9, 0.3) 100%),
    linear-gradient(180deg, rgba(3, 4, 9, 0.55) 0%, transparent 30%, transparent 70%, rgba(3, 4, 9, 0.8) 100%);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
#startScreen.leaving { opacity: 0; transform: scale(1.03); pointer-events: none; }
.start-glow { position: absolute; right: -5%; top: 40%; width: 55vw; height: 55vw; transform: translateY(-50%); background: radial-gradient(circle, rgba(255, 36, 56, 0.12), transparent 62%); pointer-events: none; }
.start-top { position: absolute; top: max(22px, env(safe-area-inset-top)); left: clamp(22px, 6vw, 96px); right: clamp(22px, 6vw, 96px); display: flex; justify-content: space-between; align-items: center; font-family: var(--display); font-size: 8px; letter-spacing: 0.28em; color: #8d96aa; }
.kf-mark { display: flex; align-items: center; gap: 9px; color: #cfd6e4; }
.kf-bars { display: flex; gap: 2px; }
.kf-bars i { width: 3px; height: 11px; background: var(--red); box-shadow: 0 0 8px rgba(255, 36, 56, 0.5); transform: skewX(-16deg); }
.kf-bars i:nth-child(2) { height: 7px; align-self: center; opacity: 0.7; }
.kf-bars i:nth-child(3) { height: 4px; align-self: center; opacity: 0.4; }
.start-top-right span { color: var(--red); margin: 0 6px; }

.title-block { position: relative; z-index: 2; max-width: 720px; }
.eyebrow { display: flex; align-items: center; gap: 12px; font-family: var(--display); font-size: clamp(6.5px, 0.72vw, 9px); letter-spacing: 0.32em; color: #a4adc0; margin-bottom: 14px; }
.eyebrow .line { width: clamp(18px, 4vw, 52px); height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 36, 56, 0.8)); }
.eyebrow .line:last-child { background: linear-gradient(90deg, rgba(255, 36, 56, 0.8), transparent); }

.title { margin: 0; font-family: var(--display); font-weight: 900; line-height: 0.8; letter-spacing: -0.035em; display: flex; flex-direction: column; }
.title-knight {
  font-size: clamp(58px, 9.4vw, 150px);
  background: linear-gradient(180deg, #fdfefe 0%, #c9d4e6 30%, #6a7387 47%, #f2f7ff 51%, #aab5c9 66%, #596174 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 0 rgba(0, 0, 0, 0.55)) drop-shadow(0 0 34px rgba(180, 210, 255, 0.14));
  transform: scaleX(0.98);
  transform-origin: left;
}
.title-rider {
  position: relative; font-size: clamp(72px, 11.8vw, 186px); font-style: italic; transform: skewX(-7deg);
  background: linear-gradient(180deg, #fff 0%, #ff5a4d 30%, #a30718 52%, #ff7466 56%, #7a0210 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 3px 0 rgba(56, 0, 4, 0.8)) drop-shadow(0 0 42px rgba(255, 36, 56, 0.4));
  padding-right: 0.16em;
}
.title-3d {
  display: inline-block; font-size: 0.16em; vertical-align: super; margin-left: 0.12em; padding: 0.32em 0.5em;
  background: var(--red); color: #fff; font-style: normal; transform: skewX(7deg) translateY(-0.2em);
  letter-spacing: 0.08em; box-shadow: 0 0 24px rgba(255, 36, 56, 0.6);
}
.scanner-strip { display: flex; gap: clamp(2px, 0.28vw, 4px); width: fit-content; margin: clamp(12px, 1.6vw, 20px) 0 clamp(12px, 1.6vw, 18px); padding: 5px 8px; background: rgba(4, 5, 10, 0.8); border: 1px solid rgba(255, 36, 56, 0.28); transform: skewX(-10deg); }
.scanner-strip span { width: clamp(13px, 1.5vw, 21px); height: clamp(6px, 0.7vw, 9px); background: #3d0a10; box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.8); transition: background 0.04s, box-shadow 0.04s; }
.scanner-strip span.on { background: var(--red-hot); box-shadow: 0 0 16px var(--red), 0 0 5px #fff inset; }
.scanner-strip.small { margin: 14px auto 8px; }
.scanner-strip.danger span.on { background: #ff5722; box-shadow: 0 0 16px #ff3b1f, 0 0 5px #fff inset; }
.tagline { margin: 0 0 10px; font-family: var(--body); font-size: clamp(17px, 1.9vw, 24px); font-weight: 600; letter-spacing: 0.04em; color: #f0f4ff; }
