.start-btn { position: relative; display: block; width: clamp(240px, 24vw, 310px); padding: 0; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%); background: linear-gradient(120deg, #ff2438, #a8081a 60%, #6d0210); box-shadow: 0 0 40px rgba(255, 36, 56, 0.4); transition: transform 0.2s, filter 0.2s; }
.start-btn::before { content: ""; position: absolute; inset: 1px; background: linear-gradient(120deg, rgba(20, 2, 4, 0.94), rgba(45, 4, 10, 0.9)); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%); }
.start-btn:hover { transform: translateY(-2px); filter: brightness(1.2); }
.start-btn:active { transform: translateY(0) scale(0.99); }
.start-btn-inner { position: relative; display: flex; align-items: center; gap: 13px; padding: 14px 18px; }
.start-icon { width: 31px; height: 31px; display: grid; place-items: center; background: var(--red); color: #fff; font-size: 10px; clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%); box-shadow: 0 0 20px rgba(255, 36, 56, 0.7); }
