.ctrl span { margin-left: 5px; font-size: 9px; letter-spacing: 0.18em; color: var(--muted); font-weight: 600; }

.start-side { position: absolute; right: clamp(24px, 5vw, 80px); bottom: 20%; display: flex; align-items: flex-end; gap: 16px; font-family: var(--display); font-size: 7.5px; line-height: 1.9; letter-spacing: 0.15em; color: #6d7689; text-align: right; }
