.start-bottom { position: absolute; left: clamp(22px, 6vw, 96px); right: clamp(22px, 6vw, 96px); bottom: max(18px, env(safe-area-inset-bottom)); display: flex; justify-content: space-between; font-family: var(--display); font-size: 7px; letter-spacing: 0.22em; color: #5b6375; }
