/* ============================ MODALS ============================ */
.modal { display: grid; place-items: center; background: rgba(2, 3, 8, 0.62); backdrop-filter: blur(10px); padding: 20px; z-index: 20; }
.modal-card { width: min(480px, 100%); padding: clamp(24px, 3.4vw, 40px); background: linear-gradient(160deg, rgba(12, 15, 25, 0.97), rgba(4, 5, 11, 0.98)); border: 1px solid rgba(255, 255, 255, 0.12); position: relative; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%); box-shadow: 0 30px 100px rgba(0, 0, 0, 0.8); text-align: center; animation: modalIn 0.35s cubic-bezier(0.2, 0.9, 0.25, 1) both; }
@keyframes modalIn { from { opacity: 0; transform: translateY(18px) scale(0.97); } to { opacity: 1; transform: none; } }
