.modal-copy { color: #9aa4b8; font-size: 14px; letter-spacing: 0.03em; margin: 4px 0 22px; }
.modal-actions { display: flex; gap: 10px; justify-content: center; margin-top: 22px; flex-wrap: wrap; }
.btn { font-family: var(--display); font-size: 11px; font-weight: 700; letter-spacing: 0.2em; padding: 13px 26px; transition: 0.2s; border: 1px solid transparent; }
.btn.primary { background: var(--red); color: #fff; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%); box-shadow: 0 0 30px rgba(255, 36, 56, 0.45); }
