.modal-hint { margin-top: 18px; font-family: var(--display); font-size: 7px; letter-spacing: 0.26em; color: #5a6276; }

.debrief { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: rgba(255, 255, 255, 0.08); margin: 20px 0 0; border: 1px solid rgba(255, 255, 255, 0.08); }
.debrief-stat { background: #080a12; padding: 13px 8px; display: flex; flex-direction: column; gap: 4px; }
