  .title-knight { font-size: clamp(52px, 16vw, 86px); }
  .title-rider { font-size: clamp(66px, 20vw, 108px); }
  .eyebrow { font-size: 6px; letter-spacing: 0.22em; margin-bottom: 10px; }
  .tagline { font-size: 16px; }
  .start-btn { width: 100%; max-width: 300px; }
  .start-glow { top: 32%; width: 90vw; height: 90vw; }
  .start-top { left: 20px; right: 20px; }
  .hud-top { gap: 8px; }
  .mission-kicker { font-size: 6.5px; }
  .mission-kicker .slash, .mission-kicker span:last-child { display: none; }
  .score-label { font-size: 7px; }
  .hud-bottom { gap: 8px; }
  .defense { width: 118px; }
  .micro-label { font-size: 6px; }
  .shield-row { gap: 3px; }
  .shield-row i { height: 7px; }
  .speed-ring { width: 104px; }
  .speed-number { font-size: 30px; }
  .scanner-hud { gap: 2px; padding: 4px 7px; }
  .scanner-hud span { width: 8px; height: 5px; }
  .speed-unit { font-size: 6px; }
  .hud-right { margin-top: 62px; }
  .toast { font-size: 12px; letter-spacing: 0.12em; }
  .modal-card { padding: 22px 16px; }
  .debrief { grid-template-columns: repeat(2, 1fr); }
