  .mission-stats { margin-top: 3px; }
  .score-value { font-size: 22px; }
  .speed-ring { width: 92px; }
  .speed-number { font-size: 26px; }
  .scanner-hud { display: none; }
  .defense { width: 120px; padding: 6px 9px; }
  .hud-right { margin-top: 6px; }
  .target-lock { top: 32%; }
