}
@media (prefers-reduced-motion: reduce) {
  #grain { animation: none; }
  .start-scan i, .load-scanner i { animation-duration: 3s; }
}

import * as THREE from "three";

const texCache = new Map();

function canvas(w, h) {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  return { c, g: c.getContext("2d") };
}

function finish(c, { repeat = false, srgb = true, aniso = 8 } = {}) {
  const t = new THREE.CanvasTexture(c);
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  if (repeat) {
    t.wrapS = THREE.RepeatWrapping;
    t.wrapT = THREE.RepeatWrapping;
  }
  t.anisotropy = aniso;
  t.needsUpdate = true;
  return t;
}

export function glowTexture() {
  if (texCache.has("glow")) return texCache.get("glow");
  const { c, g } = canvas(128, 128);
  const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, "rgba(255,255,255,1)");
  grad.addColorStop(0.18, "rgba(255,255,255,0.85)");
  grad.addColorStop(0.42, "rgba(255,255,255,0.28)");
  grad.addColorStop(0.72, "rgba(255,255,255,0.06)");
  grad.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grad;
  g.fillRect(0, 0, 128, 128);
  const t = finish(c, { srgb: true });
  texCache.set("glow", t);
  return t;
}

export function shadowTexture() {
  if (texCache.has("shadow")) return texCache.get("shadow");
  const { c, g } = canvas(128, 128);
  const grad = g.createRadialGradient(64, 64, 4, 64, 64, 64);
  grad.addColorStop(0, "rgba(0,0,0,0.92)");
  grad.addColorStop(0.5, "rgba(0,0,0,0.55)");
  grad.addColorStop(0.82, "rgba(0,0,0,0.12)");
  grad.addColorStop(1, "rgba(0,0,0,0)");
  g.fillStyle = grad;
  g.fillRect(0, 0, 128, 128);
  const t = finish(c, { srgb: false });
  texCache.set("shadow", t);
  return t;
}

export function asphaltTexture() {
  if (texCache.has("asphalt")) return texCache.get("asphalt");
  const W = 512;
  const H = 1024;
  const { c, g } = canvas(W, H);

  g.fillStyle = "#15161d";
  g.fillRect(0, 0, W, H);

  // Large scale mottling
  for (let i = 0; i < 220; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const r = 12 + Math.random() * 70;
    const a = 0.015 + Math.random() * 0.05;
    const light = Math.random() > 0.45;
    const grad = g.createRadialGradient(x, y, 0, x, y, r);
    grad.addColorStop(0, light ? `rgba(120,124,140,${a})` : `rgba(0,0,0,${a * 1.6})`);
    grad.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = grad;
    g.fillRect(x - r, y - r, r * 2, r * 2);
  }

  // Aggregate speckle
  for (let i = 0; i < 26000; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const v = 30 + Math.random() * 95;
    g.fillStyle = `rgba(${v},${v},${v + Math.random() * 18},${0.1 + Math.random() * 0.35})`;
    const s = Math.random() < 0.88 ? 1 : 2;
    g.fillRect(x, y, s, s);
  }

  // Tire polished tracks through each lane
  const laneCenters = [-6.75, -2.25, 2.25, 6.75];
  for (const lx of laneCenters) {
    for (const off of [-0.72, 0.72]) {
      const x = ((lx + off + 9) / 18) * W;
      const grad = g.createLinearGradient(x - 16, 0, x + 16, 0);
      grad.addColorStop(0, "rgba(0,0,0,0)");
      grad.addColorStop(0.5, "rgba(0,0,0,0.22)");
      grad.addColorStop(1, "rgba(0,0,0,0)");
      g.fillStyle = grad;
      g.fillRect(x - 17, 0, 34, H);
      g.fillStyle = "rgba(150,160,180,0.028)";
      g.fillRect(x - 12, 0, 24, H);
    }
  }

  // Lane markings. Texture covers 18m wide x 32m long.
  const xFor = (m) => ((m + 9) / 18) * W;
  const dashTop = 0;
  const period = H / 4; // 8 m
  const dashLen = period * 0.375; // 3 m
  for (const laneX of [-4.5, 0, 4.5]) {
    const x = xFor(laneX);
    g.fillStyle = "rgba(228,232,240,0.82)";
    for (let i = 0; i < 4; i++) {
      g.fillRect(x - 3, dashTop + i * period, 6, dashLen);
    }
    g.fillStyle = "rgba(228,232,240,0.06)";
    g.fillRect(x - 7, 0, 14, H);
  }
  // Edge lines
  for (const edge of [-8.55, 8.55]) {
    const x = xFor(edge);
    g.fillStyle = "rgba(230,234,242,0.72)";
    g.fillRect(x - 3, 0, 6, H);
    g.fillStyle = "rgba(255,255,255,0.1)";
    g.fillRect(x - 5, 0, 10, H);
  }
  // Slight yellow tint on left edge
  g.fillStyle = "rgba(255,196,92,0.5)";
  g.fillRect(xFor(-8.55) - 1, 0, 2, H);

  // Cracks
  g.strokeStyle = "rgba(6,6,8,0.5)";
  g.lineWidth = 2;
  for (let i = 0; i < 9; i++) {
    let x = Math.random() * W;
    let y = Math.random() * H;
    g.beginPath();
    g.moveTo(x, y);
    for (let s = 0; s < 6; s++) {
      x += (Math.random() - 0.5) * 42;
      y += 18 + Math.random() * 26;
      g.lineTo(x, y);
    }
    g.stroke();
  }

  // Reflective dots along the shoulder
  for (const edge of [-8.15, 8.15]) {
    for (let i = 0; i < 4; i++) {
      const x = xFor(edge);
      const y = i * period + period * 0.5;
      g.fillStyle = "rgba(255,210,120,0.95)";
      g.beginPath();
      g.arc(x, y, 2.4, 0, Math.PI * 2);
      g.fill();
    }
  }

  const t = finish(c, { repeat: true, aniso: 16 });
  texCache.set("asphalt", t);
  return t;
}

export function asphaltRoughness() {
  if (texCache.has("asphaltRough")) return texCache.get("asphaltRough");
  const W = 256;
  const H = 512;
  const { c, g } = canvas(W, H);
  g.fillStyle = "#b8b8b8";
  g.fillRect(0, 0, W, H);
  for (let i = 0; i < 7000; i++) {
    const v = 100 + Math.random() * 120;
    g.fillStyle = `rgba(${v},${v},${v},${Math.random() * 0.4})`;
    g.fillRect(Math.random() * W, Math.random() * H, 1, 1 + Math.random() * 2);
  }
  // darker (smoother) tire tracks
  for (const lx of [-6.75, -2.25, 2.25, 6.75]) {
    for (const off of [-0.72, 0.72]) {
      const x = ((lx + off + 9) / 18) * W;
      const grad = g.createLinearGradient(x - 10, 0, x + 10, 0);
      grad.addColorStop(0, "rgba(0,0,0,0)");
      grad.addColorStop(0.5, "rgba(40,40,40,0.65)");
      grad.addColorStop(1, "rgba(0,0,0,0)");
      g.fillStyle = grad;
      g.fillRect(x - 10, 0, 20, H);
    }
  }
  const t = finish(c, { repeat: true, srgb: false, aniso: 8 });
  texCache.set("asphaltRough", t);
  return t;
}

export function signTexture(title, subtitle, accent = "#ffb648") {
  const key = `sign:${title}:${subtitle}`;
  if (texCache.has(key)) return texCache.get(key);
  const W = 768;
  const H = 384;
  const { c, g } = canvas(W, H);
  g.fillStyle = "#0a0d14";
  g.fillRect(0, 0, W, H);
  g.strokeStyle = "rgba(255,255,255,0.2)";
  g.lineWidth = 6;
  g.strokeRect(18, 18, W - 36, H - 36);
  g.fillStyle = accent;
  g.fillRect(40, 52, W - 80, 5);
  g.font = "900 92px 'Orbitron', Arial Black, sans-serif";
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.fillStyle = "#f4f7ff";
  g.shadowColor = accent;
  g.shadowBlur = 26;
  g.fillText(title, W / 2, H / 2 - 8);
  g.shadowBlur = 0;
  g.font = "600 32px 'Rajdhani', Arial, sans-serif";
  g.fillStyle = "rgba(220,228,244,0.8)";
  g.fillText(subtitle, W / 2, H / 2 + 74);
  g.fillStyle = "rgba(255,255,255,0.16)";
  g.fillRect(40, H - 58, W - 80, 2);
  const t = finish(c, { srgb: true, aniso: 8 });
  texCache.set(key, t);
  return t;
}

export function plateTexture(text = "KITT") {
  const { c, g } = canvas(256, 128);
  g.fillStyle = "#e8e9ee";
  g.fillRect(0, 0, 256, 128);
  g.fillStyle = "#0a0b10";
  g.fillRect(6, 6, 244, 116);
  g.fillStyle = "#f5f6fa";
  g.fillRect(10, 10, 236, 108);
  g.font = "900 66px 'Orbitron', Arial Black, sans-serif";
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.fillStyle = "#11131a";
  g.fillText(text, 128, 68);
  g.font = "600 15px Arial, sans-serif";
  g.fillStyle = "#5d6270";
  g.fillText("CALIFORNIA · KNIGHT", 128, 18);
  return finish(c);
}

export function moonTexture() {
  const { c, g } = canvas(256, 256);
  const glow = g.createRadialGradient(128, 128, 34, 128, 128, 128);
  glow.addColorStop(0, "rgba(220,230,255,0.55)");
  glow.addColorStop(0.32, "rgba(180,196,255,0.16)");
  glow.addColorStop(1, "rgba(120,140,255,0)");
  g.fillStyle = glow;
  g.fillRect(0, 0, 256, 256);
  g.fillStyle = "#e9edff";
  g.beginPath();
  g.arc(128, 128, 34, 0, Math.PI * 2);
  g.fill();
  g.fillStyle = "rgba(160,170,205,0.35)";
  for (const [x, y, r] of [[116, 118, 6], [139, 136, 4], [124, 143, 3], [142, 114, 2.5], [108, 134, 2]]) {
    g.beginPath();
    g.arc(x, y, r, 0, Math.PI * 2);
    g.fill();
  }
  return finish(c);
}

export function beamTexture() {
  const { c, g } = canvas(64, 256);
  const grad = g.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0, "rgba(255,255,255,0)");
  grad.addColorStop(0.15, "rgba(255,255,255,0.65)");
  grad.addColorStop(0.7, "rgba(255,255,255,0.95)");
  grad.addColorStop(1, "rgba(255,255,255,1)");
  g.fillStyle = grad;
  g.beginPath();
  g.moveTo(28, 0);
  g.lineTo(36, 0);
  g.lineTo(64, 256);
  g.lineTo(0, 256);
  g.closePath();
  g.fill();
  return finish(c);
}

export function makeCanvasTexture(w, h, draw, opts) {
  const { c, g } = canvas(w, h);
  draw(g, w, h);
  return finish(c, opts);
}

import * as THREE from "three";
import { glowTexture, shadowTexture, plateTexture } from "./textures.js";

const GOLD = new THREE.Color("#d7a648");

function wedgeGeometry(w, h, l, { frontDrop = 0.22, topFrontScale = 0.9, bottomFrontScale = 0.88 } = {}) {
  const geo = new THREE.BoxGeometry(w, h, l, 1, 1, 1);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    let x = pos.getX(i);
    let y = pos.getY(i);
    const z = pos.getZ(i);
    const t = (z + l / 2) / l; // 0 at front, 1 at rear
    if (y > 0) {
      y -= frontDrop * Math.pow(1 - t, 1.35);
      x *= topFrontScale + (1 - topFrontScale) * t;
    } else {
      x *= bottomFrontScale + (1 - bottomFrontScale) * t;
    }
    pos.setXYZ(i, x, y, z);
  }
  geo.computeVertexNormals();
  return geo;
}

function cabinGeometry(w, h, l) {
  const geo = new THREE.BoxGeometry(w, h, l, 1, 1, 1);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    let x = pos.getX(i);
    let y = pos.getY(i);
    let z = pos.getZ(i);
    if (y > 0) {
      x *= 0.8;
      z += l * 0.18;
    } else {
      x *= 1;
      z -= l * 0.03;
    }
    pos.setXYZ(i, x, y, z);
  }
  geo.computeVertexNormals();
  return geo;
}

function wheel(r = 0.37, width = 0.27) {
  const g = new THREE.Group();
  const tire = new THREE.Mesh(
    new THREE.CylinderGeometry(r, r, width, 22),
    new THREE.MeshStandardMaterial({ color: "#07080b", roughness: 0.92, metalness: 0.02 })
  );
  tire.rotation.z = Math.PI / 2;

  const rim = new THREE.Mesh(
    new THREE.CylinderGeometry(r * 0.62, r * 0.62, width + 0.012, 18),
    new THREE.MeshStandardMaterial({ color: "#b9c0cc", roughness: 0.22, metalness: 0.95 })
  );
  rim.rotation.z = Math.PI / 2;

  const hub = new THREE.Mesh(
    new THREE.CylinderGeometry(r * 0.18, r * 0.18, width + 0.03, 12),
    new THREE.MeshStandardMaterial({ color: "#3c414b", roughness: 0.4, metalness: 0.8 })
  );
  hub.rotation.z = Math.PI / 2;

  g.add(tire, rim, hub);
  // spokes
  const spokeMat = new THREE.MeshStandardMaterial({ color: "#d7dce6", roughness: 0.25, metalness: 0.9 });
  for (let i = 0; i < 5; i++) {
    const spoke = new THREE.Mesh(new THREE.BoxGeometry(width + 0.04, r * 0.1, r * 0.92), spokeMat);
    spoke.rotation.x = (i / 5) * Math.PI * 2;
    g.add(spoke);
  }
  return g;
}

function blobShadow(w, l, opacity = 0.85) {
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(w, l),
    new THREE.MeshBasicMaterial({
      map: shadowTexture(),
      transparent: true,
      opacity,
      depthWrite: false,
      color: "#000000",
    })
  );
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.015;
  mesh.renderOrder = 1;
  return mesh;
}

export function buildKitt() {
  const group = new THREE.Group();
  group.name = "KITT";

  const bodyMat = new THREE.MeshPhysicalMaterial({
    color: "#07080d",
    roughness: 0.24,
    metalness: 0.72,
    clearcoat: 1,
    clearcoatRoughness: 0.09,
    envMapIntensity: 1.1,
  });
  const trimMat = new THREE.MeshStandardMaterial({ color: "#0b0d13", roughness: 0.4, metalness: 0.6 });
  const glassMat = new THREE.MeshPhysicalMaterial({
    color: "#0c1626",
    roughness: 0.08,
    metalness: 0.55,
    clearcoat: 1,
    clearcoatRoughness: 0.03,
    transparent: true,
    opacity: 0.94,
  });
  const goldMat = new THREE.MeshStandardMaterial({
    color: GOLD,
    emissive: new THREE.Color("#6b4a10"),
    emissiveIntensity: 0.35,
    metalness: 0.95,
    roughness: 0.3,
  });

  // Main wedge body
  const body = new THREE.Mesh(wedgeGeometry(2.02, 0.56, 4.86), bodyMat);
  body.position.y = 0.58;
  group.add(body);

  // Lower rocker / skirt
  const skirt = new THREE.Mesh(new THREE.BoxGeometry(1.88, 0.2, 4.55), trimMat);
  skirt.position.y = 0.3;
  group.add(skirt);

  // Nose + bumper
  const nose = new THREE.Mesh(wedgeGeometry(1.92, 0.3, 0.9, { frontDrop: 0.12, topFrontScale: 0.86, bottomFrontScale: 0.9 }), bodyMat);
  nose.position.set(0, 0.5, -2.28);
  group.add(nose);
  const bumper = new THREE.Mesh(new THREE.BoxGeometry(1.94, 0.16, 0.3), trimMat);
  bumper.position.set(0, 0.36, -2.44);
  group.add(bumper);

  // Hood plate with subtle raised center
  const hood = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.035, 1.55), bodyMat);
  hood.position.set(0, 0.845, -1.35);
  hood.rotation.x = 0.035;
  group.add(hood);

  // Cabin
  const cabin = new THREE.Mesh(cabinGeometry(1.66, 0.56, 1.85), glassMat);
  cabin.position.set(0, 1.06, 0.32);
  group.add(cabin);

  // T-top roof spine + targa panels
  const roof = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.06, 1.28), bodyMat);
  roof.position.set(0, 1.35, 0.5);
  group.add(roof);
  for (const side of [-1, 1]) {
    const ttop = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.04, 1.02), glassMat);
    ttop.position.set(side * 0.42, 1.345, 0.46);
    group.add(ttop);
  }

  // Rear deck + spoiler
  const deck = new THREE.Mesh(new THREE.BoxGeometry(1.78, 0.05, 1.2), bodyMat);
  deck.position.set(0, 0.875, 1.72);
  group.add(deck);
  const spoiler = new THREE.Mesh(new THREE.BoxGeometry(1.78, 0.07, 0.3), trimMat);
  spoiler.position.set(0, 1.02, 2.28);
  spoiler.rotation.x = -0.09;
  group.add(spoiler);
  for (const side of [-1, 1]) {
    const strut = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.17, 0.13), trimMat);
    strut.position.set(side * 0.62, 0.93, 2.31);
    group.add(strut);
  }

  // Gold pinstripes along the flanks
  for (const side of [-1, 1]) {
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.018, 4.1), goldMat);
    stripe.position.set(side * 0.985, 0.79, 0.02);
    group.add(stripe);
    const lowStripe = new THREE.Mesh(new THREE.BoxGeometry(0.008, 0.01, 3.6), goldMat);
    lowStripe.position.set(side * 0.972, 0.45, 0.04);
    group.add(lowStripe);
  }
  // Hood pinstripes
  for (const side of [-1, 1]) {
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.008, 1.5), goldMat);
    stripe.position.set(side * 0.6, 0.87, -1.35);
    stripe.rotation.x = 0.035;
    group.add(stripe);
  }

  // Scanner housing + segments
  const scannerGroup = new THREE.Group();
  scannerGroup.position.set(0, 0.735, -2.43);
  const housing = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.155, 0.1), new THREE.MeshStandardMaterial({ color: "#050607", roughness: 0.35, metalness: 0.5 }));
  scannerGroup.add(housing);
  const segments = [];
  const segW = 0.108;
  const segGap = 0.022;
  const total = 8 * segW + 7 * segGap;
  for (let i = 0; i < 8; i++) {
    const mat = new THREE.MeshBasicMaterial({ color: "#ff1a2e", toneMapped: false });
    const seg = new THREE.Mesh(new THREE.BoxGeometry(segW, 0.075, 0.04), mat);
    seg.position.x = -total / 2 + segW / 2 + i * (segW + segGap);
    seg.position.z = -0.045;
    segments.push(seg);
    scannerGroup.add(seg);
  }
  const scannerGlow = new THREE.Mesh(
    new THREE.PlaneGeometry(2.1, 0.62),
    new THREE.MeshBasicMaterial({
      map: glowTexture(),
      color: "#ff2030",
      transparent: true,
      opacity: 0.55,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    })
  );
  scannerGlow.position.set(0, 0, -0.12);
  scannerGroup.add(scannerGlow);
  const scannerLight = new THREE.PointLight("#ff1528", 4, 7, 2);
  scannerLight.position.set(0, 0.05, -0.25);
  scannerGroup.add(scannerLight);
  group.add(scannerGroup);

  // Headlights
  const headlights = [];
  const headMat = new THREE.MeshBasicMaterial({ color: "#eaf4ff", toneMapped: false });
  for (const side of [-1, 1]) {
    const hl = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.115, 0.03), headMat);
    hl.position.set(side * 0.63, 0.625, -2.455);
    group.add(hl);
    headlights.push(hl);
    const spot = new THREE.SpotLight("#cfe4ff", 55, 46, 0.42, 0.65, 1.4);
    spot.position.set(side * 0.63, 0.63, -2.4);
    spot.target.position.set(side * 1.2, -0.4, -22);
    group.add(spot, spot.target);
  }

  // Turn indicators
  const indicatorMat = new THREE.MeshBasicMaterial({ color: "#ff9e2c", toneMapped: false });
  for (const side of [-1, 1]) {
    const ind = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.06, 0.02), indicatorMat);
    ind.position.set(side * 0.88, 0.55, -2.45);
    group.add(ind);
  }

  // Taillights
  const brakeLights = [];
  for (const side of [-1, 1]) {
    const mat = new THREE.MeshBasicMaterial({ color: "#8e0712", toneMapped: false });
    const bar = new THREE.Mesh(new THREE.BoxGeometry(0.64, 0.1, 0.025), mat);
    bar.position.set(side * 0.56, 0.7, 2.45);
    group.add(bar);
    brakeLights.push(bar);
    const halo = new THREE.Mesh(
      new THREE.PlaneGeometry(0.85, 0.3),
      new THREE.MeshBasicMaterial({ map: glowTexture(), color: "#ff1a2e", transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    halo.position.set(side * 0.56, 0.7, 2.47);
    halo.rotation.y = Math.PI;
    group.add(halo);
    brakeLights.push(halo);
  }
  // Center reflector strip
  const tailStrip = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.055, 0.02), new THREE.MeshBasicMaterial({ color: "#9b0a15", toneMapped: false }));
  tailStrip.position.set(0, 0.7, 2.455);
  group.add(tailStrip);

  // License plate
  const plate = new THREE.Mesh(
    new THREE.PlaneGeometry(0.5, 0.25),
    new THREE.MeshStandardMaterial({ map: plateTexture("KITT"), roughness: 0.6, metalness: 0.1 })
  );
  plate.position.set(0, 0.48, 2.458);
  plate.rotation.y = Math.PI;
  group.add(plate);

  // Wheels
  const wheels = [];
  const frontSteer = [];
  const wheelPositions = [
    [-0.94, 0.37, -1.55, true],
    [0.94, 0.37, -1.55, true],
    [-0.94, 0.37, 1.55, false],
    [0.94, 0.37, 1.55, false],
  ];
  for (const [x, y, z, front] of wheelPositions) {
    const pivot = new THREE.Group();
    pivot.position.set(x, y, z);
    const w = wheel(0.37, 0.28);
    pivot.add(w);
    group.add(pivot);
    wheels.push({ pivot, mesh: w, front });
    if (front) frontSteer.push(pivot);
  }

  // Exhaust flames
  const exhaust = new THREE.Group();
  const flameMat = new THREE.MeshBasicMaterial({
    color: "#ff8a2a",
    transparent: true,
    opacity: 0,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  });
  for (const side of [-1, 1]) {
    const flame = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.55, 8), flameMat.clone());
    flame.rotation.x = Math.PI / 2;
    flame.position.set(side * 0.55, 0.31, 2.6);
    exhaust.add(flame);
  }
  group.add(exhaust);

  // Underbody red glow + shadow
  const underglow = new THREE.Mesh(
    new THREE.PlaneGeometry(3.4, 6.2),
    new THREE.MeshBasicMaterial({ map: glowTexture(), color: "#c40012", transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false })
  );
  underglow.rotation.x = -Math.PI / 2;
  underglow.position.y = 0.02;
  group.add(underglow);
  const shadow = blobShadow(2.7, 5.9, 0.9);
  group.add(shadow);

  return {
    group,
    bodyMat,
    glassMat,
    segments,
    scannerGlow,
    scannerLight,
    headlights,
    brakeLights,
    wheels,
    frontSteer,
    exhaust,
    scannerGroup,
    speed: 0,
  };
}

export function updateKitt(kitt, dt, { speed = 0, steer = 0, braking = false, boost = false, time = 0, airborne = false }) {
  const speedNorm = Math.min(1, Math.abs(speed) / 90);
  for (const w of kitt.wheels) {
    w.mesh.rotation.x -= (speed * dt) / 0.37;
  }
  for (const p of kitt.frontSteer) {
    p.rotation.y = THREE.MathUtils.lerp(p.rotation.y, steer * 0.34, 1 - Math.pow(0.001, dt));
  }
  // Body attitude
  const roll = -steer * 0.045 * (0.4 + speedNorm);
  kitt.group.rotation.z = THREE.MathUtils.lerp(kitt.group.rotation.z, roll, 1 - Math.pow(0.002, dt));
  kitt.group.rotation.x = THREE.MathUtils.lerp(
    kitt.group.rotation.x,
    airborne ? -0.12 : boost ? 0.022 : braking ? -0.02 : 0.004,
    1 - Math.pow(0.005, dt)
  );

  // Scanner bounce: 0..1..0 triangular wave, smoothed
  const period = 1.15;
  const raw = (time % period) / period;
  const tri = raw < 0.5 ? raw * 2 : (1 - raw) * 2;
  const pos = tri * 7;
  let strongest = 0;
  for (let i = 0; i < kitt.segments.length; i++) {
    const d = Math.abs(i - pos);
    const v = Math.max(0, 1 - d / 1.7);
    const intensity = Math.pow(v, 1.6);
    strongest = Math.max(strongest, intensity);
    const mat = kitt.segments[i].material;
    mat.color.setRGB(1, 0.08 + 0.25 * intensity, 0.1 + 0.22 * intensity);
  }
  kitt.scannerGlow.material.opacity = 0.26 + strongest * 0.55;
  kitt.scannerGlow.material.color.setRGB(1, 0.1 + 0.14 * strongest, 0.12);
  kitt.scannerLight.intensity = 1.5 + strongest * 8;

  // Brake lights
  for (let i = 0; i < kitt.brakeLights.length; i += 2) {
    kitt.brakeLights[i].material.color.set(braking ? "#ff2334" : "#8e0712");
    kitt.brakeLights[i + 1].material.opacity = braking ? 0.75 : 0.35;
  }

  // Exhaust
  const flame = boost && !airborne;
  for (const f of kitt.exhaust.children) {
    f.material.opacity = flame ? 0.75 + Math.sin(time * 55 + f.position.x * 9) * 0.22 : 0;
    f.scale.set(1, 0.7 + Math.random() * 0.8, 1);
  }
}

