  for (const x of [-10, -4, 4, 10]) {
    const lamp = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.08, 0.3), new THREE.MeshBasicMaterial({ color: "#9ff2ff", toneMapped: false }));
    lamp.position.set(x, 9.5, 2.4);
    g.add(lamp);
    const halo = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: glowTexture(), color: "#7fe8ff", transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false, fog: false })
    );
    halo.position.set(x, 9.45, 2.4);
    halo.scale.set(3.4, 1.4, 1);
    g.add(halo);
  }
  return g;
}

function cactus() {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: "#18221c", roughness: 0.9, metalness: 0.02 });
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.24, 3.4, 7), mat);
  trunk.position.y = 1.7;
  g.add(trunk);
  const arm1 = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.14, 1.5, 6), mat);
  arm1.position.set(0.42, 2.2, 0);
  arm1.rotation.z = -0.9;
  g.add(arm1);
  const arm1b = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.12, 1.1, 6), mat);
  arm1b.position.set(0.76, 2.75, 0);
  g.add(arm1b);
  const arm2 = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.13, 1.2, 6), mat);
  arm2.position.set(-0.38, 1.7, 0);
  arm2.rotation.z = 0.95;
  g.add(arm2);
  return g;
}

export class World {
  constructor(scene) {
    this.scene = scene;
    this.time = 0;
    this.span = 640;
    this.scroller = new Scroller(this.span);
    this.roadTex = asphaltTexture().clone();
    this.roadRough = asphaltRoughness().clone();
    this.roadTex.wrapS = THREE.RepeatWrapping;
    this.roadTex.wrapT = THREE.RepeatWrapping;
    this.roadTex.repeat.set(1, 46);
    this.roadRough.repeat.set(1, 46);
    this.roadTex.needsUpdate = true;
    this.roadRough.needsUpdate = true;

    this._buildSky();
    this._buildGround();
    this._buildRoad();
    this._buildRail();
    this._buildLights();
    this._buildSigns();
    this._buildScenery();
    this._buildDistant();
  }

  _buildSky() {
    this.sky = skyDome();
    this.scene.add(this.sky);
    const s = stars();
    this.stars = s.points;
    this.starMat = s.mat;
    this.scene.add(this.stars);
    this.moon = moon();
    this.scene.add(this.moon);
  }

  _buildGround() {
    const tex = makeCanvasTexture(
      256,
      256,
      (g, w, h) => {
        g.fillStyle = "#0d0a12";
        g.fillRect(0, 0, w, h);
        for (let i = 0; i < 2600; i++) {
          const v = Math.random();
          g.fillStyle = v < 0.7 ? `rgba(40,32,52,${0.25 + Math.random() * 0.4})` : `rgba(90,74,60,${0.12 + Math.random() * 0.2})`;
          const s = Math.random() < 0.9 ? 1 : 2;
          g.fillRect(Math.random() * w, Math.random() * h, s, s);
        }
      },
      { repeat: true, srgb: true }
    );
    tex.repeat.set(90, 90);
    const mat = new THREE.MeshStandardMaterial({ map: tex, color: "#6b5c78", roughness: 1, metalness: 0 });
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(3000, 3000), mat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.04;
    ground.position.z = -700;
    this.scene.add(ground);

    // shoulders
    const shoulderMat = new THREE.MeshStandardMaterial({ color: "#18151d", roughness: 0.95 });
    for (const side of [-1, 1]) {
      const shoulder = new THREE.Mesh(new THREE.PlaneGeometry(6, 1600), shoulderMat);
      shoulder.rotation.x = -Math.PI / 2;
      shoulder.position.set(side * 12.2, 0.005, -700);
      this.scene.add(shoulder);
    }
  }

  _buildRoad() {
    const mat = new THREE.MeshStandardMaterial({
      map: this.roadTex,
      roughnessMap: this.roadRough,
      roughness: 0.62,
      metalness: 0.34,
      color: "#cfd4df",
    });
    const road = new THREE.Mesh(new THREE.PlaneGeometry(18.4, 1600, 1, 1), mat);
    road.rotation.x = -Math.PI / 2;
    road.position.z = -700;
    road.receiveShadow = false;
    this.scene.add(road);
    this.road = road;
    this.roadMat = mat;
  }

  _buildRail() {
    const railMat = new THREE.MeshStandardMaterial({ color: "#3a3f4b", roughness: 0.4, metalness: 0.9 });
    const postMat = new THREE.MeshStandardMaterial({ color: "#262a33", roughness: 0.6, metalness: 0.7 });
    const count = 160;
    this.rails = new THREE.InstancedMesh(new THREE.BoxGeometry(8.05, 0.3, 0.09), railMat, count);
    this.posts = new THREE.InstancedMesh(new THREE.BoxGeometry(0.09, 0.85, 0.09), postMat, count);
    const reflMat = new THREE.MeshBasicMaterial({ color: "#ffb648", toneMapped: false });
    this.reflectors = new THREE.InstancedMesh(new THREE.BoxGeometry(0.13, 0.11, 0.05), reflMat, count);
    this.railData = [];
    const spacing = 8;
    let idx = 0;
    for (const side of [-1, 1]) {
      for (let i = 0; i < count / 2; i++) {
        this.railData.push({ x: side * 10.35, z: 60 - i * spacing, side, phase: i });
        idx++;
      }
    }
    this.scene.add(this.rails, this.posts, this.reflectors);
    this._updateRails(0, true);
  }

  _updateRails() {
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    const s = new THREE.Vector3(1, 1, 1);
    this.railData.forEach((d, i) => {
      m.compose(new THREE.Vector3(d.x, 0.72, d.z), q, s);
      this.rails.setMatrixAt(i, m);
      m.compose(new THREE.Vector3(d.x, 0.42, d.z), q, s);
      this.posts.setMatrixAt(i, m);
      e.set(0, 0, 0);
      q.setFromEuler(e);
      m.compose(new THREE.Vector3(d.x, 0.92, d.z + 2), q, s);
      this.reflectors.setMatrixAt(i, m);
    });
    this.rails.instanceMatrix.needsUpdate = true;
    this.posts.instanceMatrix.needsUpdate = true;
    this.reflectors.instanceMatrix.needsUpdate = true;
    q.identity();
  }

  _buildLights() {
    this.lights = [];
    const spacing = 56;
    for (let i = 0; i < 12; i++) {
      const side = i % 2 === 0 ? 1 : -1;
      const light = streetlight(side);
      light.position.z = 40 - i * spacing;
      this.scene.add(light);
      this.lights.push(light);
    }
  }

  _buildSigns() {
    this.gantries = [];
    const defs = [
      ["LAS VEGAS", "61 · KNIGHT FOUNDATION TEST RANGE", "#ffb648"],
      ["SECTOR 7", "AUTHORIZED PURSUIT VEHICLES ONLY", "#ff2438"],
      ["MOJAVE 42", "K.I.T.T. PROVING GROUNDS · NEXT EXIT", "#7fe8ff"],
      ["NO SERVICES", "NEXT FUEL 118 MILES", "#ffb648"],
    ];
    for (let i = 0; i < 4; i++) {
      const tex = signTexture(defs[i][0], defs[i][1], defs[i][2]);
      const g = gantry(tex);
      g.position.z = -40 - i * 170;
      this.scene.add(g);
      this.gantries.push(g);
    }
    this.overpasses = [];
    for (let i = 0; i < 2; i++) {
      const op = overpass();
      op.position.z = -160 - i * 300;
      this.scene.add(op);
      this.overpasses.push(op);
    }
  }

  _buildScenery() {
    this.cacti = [];
    for (let i = 0; i < 10; i++) {
      const c = cactus();
      const side = i % 2 === 0 ? 1 : -1;
      c.position.set(side * (16 + Math.random() * 10), 0, 40 - i * 62);
      c.rotation.y = Math.random() * Math.PI;
      c.scale.setScalar(0.8 + Math.random() * 0.7);
      this.scene.add(c);
      this.cacti.push(c);
    }
    const rockMat = new THREE.MeshStandardMaterial({ color: "#241d2b", roughness: 0.95, flatShading: true });
    this.rocks = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1.1, 0), rockMat, 90);
    this.rockData = [];
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    for (let i = 0; i < 90; i++) {
      const side = i % 2 === 0 ? 1 : -1;
      const z = 60 - (i / 90) * this.span;
      const x = side * (15 + Math.random() * 50);
      const scale = 0.5 + Math.random() * 2.4;
      q.setFromEuler(new THREE.Euler(Math.random(), Math.random() * Math.PI, Math.random()));
      m.compose(new THREE.Vector3(x, scale * 0.3 - 0.1, z), q, new THREE.Vector3(scale, scale * (0.6 + Math.random() * 0.7), scale));
      this.rocks.setMatrixAt(i, m);
      this.rockData.push({ x, z, scale, rx: Math.random(), ry: Math.random() * Math.PI, rz: Math.random() });
    }
    this.rocks.instanceMatrix.needsUpdate = true;
    this.scene.add(this.rocks);
  }

  _buildDistant() {
    const mount1 = mountainRange(-560, 1500, 120, "#1a1128", 7);
    mount1.position.y = 0;
    this.scene.add(mount1);
    const mount2 = mountainRange(-680, 1800, 190, "#130c1e", 21);
    this.scene.add(mount2);
    this.scene.add(city());

    const glowPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(1200, 120),
      new THREE.MeshBasicMaterial({ map: glowTexture(), color: "#7d2450", transparent: true, opacity: 0.28, blending: THREE.AdditiveBlending, depthWrite: false, fog: false })
    );
    glowPlane.position.set(0, 30, -720);
    this.scene.add(glowPlane);
  }

  update(dt, speed) {
    this.time += dt;
    this.starMat.uniforms.uTime.value = this.time;
    this.roadTex.offset.y += (speed * dt) / 32;
    this.roadRough.offset.y += (speed * dt) / 32;

    this.scroller.update(speed, dt);
    for (const l of this.lights) {
      l.position.z += speed * dt;
      if (l.position.z > 70) l.position.z -= 12 * 56;
    }
    for (const g of this.gantries) {
      g.position.z += speed * dt;
      if (g.position.z > 90) g.position.z -= 4 * 170;
    }
    for (const o of this.overpasses) {
      o.position.z += speed * dt;
      if (o.position.z > 90) o.position.z -= 2 * 300;
    }
    for (const c of this.cacti) {
      c.position.z += speed * dt;
      if (c.position.z > 70) c.position.z -= 10 * 62;
    }
    for (const d of this.railData) {
      d.z += speed * dt;
      if (d.z > 70) d.z -= (this.railData.length / 2) * 8;
    }
    this._updateRails();

    // rocks scroll via instancing
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    for (let i = 0; i < this.rockData.length; i++) {
      const d = this.rockData[i];
      d.z += speed * dt;
      if (d.z > 70) d.z -= this.span;
      e.set(d.rx, d.ry, d.rz);
      q.setFromEuler(e);
      m.compose(
        new THREE.Vector3(d.x, d.scale * 0.3 - 0.1, d.z),
        q,
        new THREE.Vector3(d.scale, d.scale * (0.6 + ((i * 37) % 10) * 0.07), d.scale)
      );
      this.rocks.setMatrixAt(i, m);
    }
    this.rocks.instanceMatrix.needsUpdate = true;
  }
}

import * as THREE from "three";
import { glowTexture } from "./textures.js";

const MAX = 900;

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.positions = new Float32Array(MAX * 3);
    this.velocities = new Float32Array(MAX * 3);
    this.colors = new Float32Array(MAX * 3);
    this.sizes = new Float32Array(MAX);
    this.alphas = new Float32Array(MAX);
    this.life = new Float32Array(MAX);
    this.maxLife = new Float32Array(MAX);
    this.gravity = new Float32Array(MAX);
    this.drag = new Float32Array(MAX);
    this.cursor = 0;

    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute("aColor", new THREE.BufferAttribute(this.colors, 3));
    geo.setAttribute("aSize", new THREE.BufferAttribute(this.sizes, 1));
    geo.setAttribute("aAlpha", new THREE.BufferAttribute(this.alphas, 1));

    this.material = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uTexture: { value: glowTexture() } },
      vertexShader: `
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (260.0 / max(1.0, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        uniform sampler2D uTexture;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 tex = texture2D(uTexture, gl_PointCoord);
          gl_FragColor = vec4(vColor, tex.a * vAlpha);
        }
      `,
    });

    this.points = new THREE.Points(geo, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.geo = geo;

    this.shockwaves = [];
    this.beams = [];
    this.flashes = [];

    this.ringGeo = new THREE.RingGeometry(0.6, 0.78, 40);
  }

  _spawn(x, y, z, vx, vy, vz, color, size, life, gravity = 0, drag = 0.98) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % MAX;
    this.positions[i * 3] = x;
    this.positions[i * 3 + 1] = y;
    this.positions[i * 3 + 2] = z;
    this.velocities[i * 3] = vx;
    this.velocities[i * 3 + 1] = vy;
    this.velocities[i * 3 + 2] = vz;
    this.colors[i * 3] = color.r;
    this.colors[i * 3 + 1] = color.g;
    this.colors[i * 3 + 2] = color.b;
    this.sizes[i] = size;
    this.life[i] = life;
    this.maxLife[i] = life;
    this.alphas[i] = 1;
    this.gravity[i] = gravity;
    this.drag[i] = drag;
  }

  burst(position, { color = new THREE.Color("#ff7a2a"), count = 30, speed = 18, size = 0.55, life = 0.8, gravity = 12, spread = 1, up = 0 } = {}) {
    for (let i = 0; i < count; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 2 - 1);
      const s = speed * (0.35 + Math.random() * 0.65);
      const vx = Math.sin(phi) * Math.cos(theta) * s * spread;
      const vy = Math.abs(Math.cos(phi)) * s * 0.7 + up;
      const vz = Math.sin(phi) * Math.sin(theta) * s * spread;
      const c = color.clone();
      const tint = 0.6 + Math.random() * 0.4;
      c.multiplyScalar(tint);
      if (Math.random() < 0.25) c.lerp(new THREE.Color("#fff0c4"), 0.7);
      this._spawn(position.x, position.y, position.z, vx, vy, vz, c, size * (0.5 + Math.random() * 0.9), life * (0.5 + Math.random() * 0.7), gravity, 0.965);
    }
  }

  trail(position, color, size = 0.35, speed = 3) {
    this._spawn(
      position.x + (Math.random() - 0.5) * 0.5,
      position.y + (Math.random() - 0.5) * 0.25,
      position.z + Math.random() * 0.5,
      (Math.random() - 0.5) * 1.4,
      (Math.random() - 0.5) * 0.8,
      speed + Math.random() * 4,
      color,
      size * (0.6 + Math.random() * 0.8),
      0.3 + Math.random() * 0.25,
      -1.5,
      0.95
    );
  }

  shockwave(position, color = "#ff5a3c", maxScale = 10, life = 0.55) {
    const mat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.85,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
      toneMapped: false,
    });
    const mesh = new THREE.Mesh(this.ringGeo, mat);
    mesh.position.copy(position);
    mesh.rotation.x = -Math.PI / 2;
    mesh.scale.setScalar(0.6);
    this.scene.add(mesh);
    this.shockwaves.push({ mesh, t: 0, life, maxScale });
  }

  explosion(position) {
    this.burst(position, { color: new THREE.Color("#ff6a1e"), count: 55, speed: 22, size: 0.8, life: 1.1, gravity: 9 });
    this.burst(position, { color: new THREE.Color("#ffe6a0"), count: 22, speed: 30, size: 0.45, life: 0.55, gravity: 3 });
    this.burst(position, { color: new THREE.Color("#7b1a0c"), count: 18, speed: 8, size: 1.5, life: 1.4, gravity: -1 });
    this.shockwave(position, "#ff7a2a", 12, 0.6);
    const light = new THREE.PointLight("#ff7a2a", 60, 26, 2);
    light.position.copy(position).add(new THREE.Vector3(0, 1, 0));
    this.scene.add(light);
    this.flashes.push({ light, t: 0, life: 0.35 });
  }

  sparks(position, color = "#ffd8a0") {
    this.burst(position, { color: new THREE.Color(color), count: 16, speed: 10, size: 0.22, life: 0.45, gravity: 16, spread: 1.4 });
  }

  pickup(position) {
    this.burst(position, { color: new THREE.Color("#ffcf6b"), count: 26, speed: 8, size: 0.45, life: 0.7, gravity: 2, spread: 1.2 });
    this.shockwave(position, "#ffcf6b", 5, 0.4);
  }

  laser(from, to, color = "#9ff4ff") {
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length();
    const geo = new THREE.CylinderGeometry(0.035, 0.07, 1, 6, 1, true);
    const mat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 1,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(from).add(to).multiplyScalar(0.5);
    mesh.scale.set(1, len, 1);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
    this.scene.add(mesh);
    const glow = new THREE.Mesh(
      new THREE.PlaneGeometry(0.55, len),
      new THREE.MeshBasicMaterial({ map: glowTexture(), color, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false, side: THREE.DoubleSide })
    );
    glow.position.copy(to).add(from).multiplyScalar(0.5);
    glow.quaternion.copy(mesh.quaternion);
    glow.rotateY(Math.PI / 2);
    this.scene.add(glow);
    this.beams.push({ mesh, glow, t: 0, life: 0.16 });
  }

  update(dt) {
    for (let i = 0; i < MAX; i++) {
      if (this.life[i] <= 0) {
        this.alphas[i] = 0;
        continue;
      }
      this.life[i] -= dt;
      const t = Math.max(0, this.life[i] / this.maxLife[i]);
      this.alphas[i] = Math.pow(t, 0.65);
      const drag = this.drag[i];
      this.velocities[i * 3] *= drag;
      this.velocities[i * 3 + 1] = this.velocities[i * 3 + 1] * drag - this.gravity[i] * dt;
      this.velocities[i * 3 + 2] *= drag;
      this.positions[i * 3] += this.velocities[i * 3] * dt;
      this.positions[i * 3 + 1] += this.velocities[i * 3 + 1] * dt;
      this.positions[i * 3 + 2] += this.velocities[i * 3 + 2] * dt;
      if (this.positions[i * 3 + 1] < 0.05) {
        this.positions[i * 3 + 1] = 0.05;
        this.velocities[i * 3 + 1] *= -0.28;
      }
      this.sizes[i] *= 0.995;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;

    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const s = this.shockwaves[i];
      s.t += dt;
      const k = s.t / s.life;
      s.mesh.scale.setScalar(0.6 + k * s.maxScale);
      s.mesh.material.opacity = (1 - k) * 0.85;
      if (k >= 1) {
        this.scene.remove(s.mesh);
        s.mesh.material.dispose();
        this.shockwaves.splice(i, 1);
      }
    }
    for (let i = this.beams.length - 1; i >= 0; i--) {
      const b = this.beams[i];
      b.t += dt;
      const k = b.t / b.life;
      b.mesh.material.opacity = Math.max(0, 1 - k);
      b.glow.material.opacity = Math.max(0, 0.6 - k * 0.6);
      b.mesh.scale.x = 1 - k * 0.5;
      b.mesh.scale.z = 1 - k * 0.5;
      if (k >= 1) {
        this.scene.remove(b.mesh, b.glow);
        b.mesh.material.dispose();
        b.glow.material.dispose();
        b.mesh.geometry.dispose();
        b.glow.geometry.dispose();
        this.beams.splice(i, 1);
      }
    }
    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i];
      f.t += dt;
      f.light.intensity = 60 * Math.max(0, 1 - f.t / f.life);
      if (f.t >= f.life) {
        this.scene.remove(f.light);
        f.light.dispose();
        this.flashes.splice(i, 1);
      }
    }
  }
}

const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.started = false;
    this.mode = "menu";
    this.scannerTimer = 0;
    this.scannerSide = 1;
    this.musicStep = 0;
    this.nextNoteTime = 0;
    this.lastUpdate = 0;
    this.noiseBuffer = null;
  }

  init() {
    if (this.ctx) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) {
      this.enabled = false;
      return;
    }
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.85;
    this.comp = this.ctx.createDynamicsCompressor();
    this.comp.threshold.value = -14;
    this.comp.knee.value = 18;
    this.comp.ratio.value = 5;
    this.comp.attack.value = 0.004;
    this.comp.release.value = 0.22;
    this.master.connect(this.comp);
    this.comp.connect(this.ctx.destination);

    this.musicBus = this.ctx.createGain();
    this.musicBus.gain.value = 0.22;
    this.musicBus.connect(this.master);

    this.sfxBus = this.ctx.createGain();
    this.sfxBus.gain.value = 0.5;
    this.sfxBus.connect(this.master);

    this.delay = this.ctx.createDelay(1);
    this.delay.delayTime.value = 0.24;
    const feedback = this.ctx.createGain();
    feedback.gain.value = 0.24;
    const wet = this.ctx.createGain();
    wet.gain.value = 0.18;
    this.delay.connect(feedback);
    feedback.connect(this.delay);
    this.delay.connect(wet);
    wet.connect(this.musicBus);

    this._makeNoise();
    this._initEngine();
  }

  _makeNoise() {
    const len = this.ctx.sampleRate * 2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buf;
  }

  _initEngine() {
    const ctx = this.ctx;
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = "lowpass";
    this.engineFilter.frequency.value = 340;
    this.engineFilter.Q.value = 3.2;
    this.engineFilter.connect(this.engineGain);
    this.engineGain.connect(this.sfxBus);

    this.engineOsc1 = ctx.createOscillator();
    this.engineOsc1.type = "sawtooth";
    this.engineOsc1.frequency.value = 42;
    this.engineOsc2 = ctx.createOscillator();
    this.engineOsc2.type = "square";
    this.engineOsc2.frequency.value = 21;
    const g2 = ctx.createGain();
    g2.gain.value = 0.45;
    this.engineOsc1.connect(this.engineFilter);
    this.engineOsc2.connect(g2);
    g2.connect(this.engineFilter);
    this.engineOsc1.start();
    this.engineOsc2.start();

    this.engineNoise = ctx.createBufferSource();
    this.engineNoise.buffer = this.noiseBuffer;
    this.engineNoise.loop = true;
    this.engineNoiseFilter = ctx.createBiquadFilter();
    this.engineNoiseFilter.type = "bandpass";
    this.engineNoiseFilter.frequency.value = 180;
    this.engineNoiseFilter.Q.value = 0.8;
    this.engineNoiseGain = ctx.createGain();
    this.engineNoiseGain.gain.value = 0;
    this.engineNoise.connect(this.engineNoiseFilter);
    this.engineNoiseFilter.connect(this.engineNoiseGain);
    this.engineNoiseGain.connect(this.sfxBus);
    this.engineNoise.start();
  }

  async start() {
    this.init();
    if (!this.ctx) return;
    if (this.ctx.state === "suspended") {
      try {
        await this.ctx.resume();
      } catch {}
    }
    this.started = true;
    this.nextNoteTime = this.ctx.currentTime + 0.08;
  }

  setEnabled(on) {
    this.enabled = on;
    if (!this.ctx) return;
    this.master.gain.cancelScheduledValues(this.ctx.currentTime);
    this.master.gain.linearRampToValueAtTime(on ? 0.85 : 0, this.ctx.currentTime + 0.15);
  }

  setMode(mode) {
    this.mode = mode;
    if (!this.ctx) return;
    const target = mode === "playing" ? 0.24 : mode === "paused" ? 0.09 : 0.16;
    this.musicBus.gain.cancelScheduledValues(this.ctx.currentTime);
    this.musicBus.gain.linearRampToValueAtTime(target, this.ctx.currentTime + 0.4);
  }

  update(dt, { speedNorm = 0, boost = false, playing = false } = {}) {
    if (!this.ctx || !this.enabled) return;
    const now = this.ctx.currentTime;

    if (this.engineGain) {
      const targetGain = playing ? 0.11 + speedNorm * 0.05 : 0.018;
      this.engineGain.gain.setTargetAtTime(targetGain, now, 0.12);
      const base = 34 + speedNorm * 92 + (boost ? 22 : 0);
      this.engineOsc1.frequency.setTargetAtTime(base, now, 0.09);
      this.engineOsc2.frequency.setTargetAtTime(base * 0.5, now, 0.09);
      this.engineFilter.frequency.setTargetAtTime(240 + speedNorm * 900 + (boost ? 380 : 0), now, 0.1);
      this.engineNoiseGain.gain.setTargetAtTime(playing ? 0.02 + speedNorm * 0.035 : 0, now, 0.2);
      this.engineNoiseFilter.frequency.setTargetAtTime(140 + speedNorm * 280, now, 0.1);
    }

    if (playing || this.mode === "menu") {
      this.scannerTimer -= dt;
      if (this.scannerTimer <= 0) {
        this.scannerTimer = 1.15;
        this.scannerPing(playing ? 0.55 : 0.42);
      }
    }

    if (this.mode !== "paused") this._scheduleMusic(now);
  }

  _scheduleMusic(now) {
    if (!this.started) return;
    if (this.nextNoteTime < now - 0.4) this.nextNoteTime = now + 0.05;
    const stepDur = 60 / 96 / 4;
    while (this.nextNoteTime < now + 0.22) {
      this._playStep(this.musicStep, this.nextNoteTime, stepDur);
      this.nextNoteTime += stepDur;
      this.musicStep = (this.musicStep + 1) % 64;
    }
  }

  _playStep(step, t, stepDur) {
    const bar = Math.floor(step / 16);
    const s = step % 16;
    // Am - F - C - G
    const roots = [45, 41, 48, 43];
    const chords = [
      [57, 60, 64],
      [53, 57, 60],
      [55, 60, 64],
      [55, 59, 62],
    ];
    const root = roots[bar];
    const chord = chords[bar];

    // Arpeggio lead
    if (s % 2 === 0 || s === 7 || s === 15) {
      const order = [0, 1, 2, 1, 2, 0, 1, 2];
      const idx = order[(step % 8)] + (s >= 12 ? 12 : 0);
      const note = chord[s % 3] + 12 + (idx % 2 === 0 ? 0 : 12);
      this._tone(midi(note), t, stepDur * 1.4, "triangle", 0.055, this.musicBus, this.delay);
    }

    // Pads at start of each bar
    if (s === 0) {
      for (const n of chord) {
        this._pad(midi(n - 12), t, stepDur * 16, 0.022);
      }
    }

    // Bass eighths
    if (s % 2 === 0) {
      const bassNote = root - 12 + (s === 6 || s === 14 ? 7 : 0);
      this._tone(midi(bassNote), t, stepDur * 1.7, "sawtooth", 0.12, this.musicBus, null, 120 + (s % 4) * 60, 4);
    }

    // Drums
    if (s % 4 === 0) this._kick(t);
    if (s === 4 || s === 12) this._snare(t);
    if (s % 2 === 0) this._hat(t, s % 4 === 0 ? 0.05 : 0.03);
  }

  _tone(freq, t, dur, type, gain, bus, delaySend = null, cutoff = 0, q = 0.7) {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    let node = osc;
    if (cutoff) {
      const f = ctx.createBiquadFilter();
      f.type = "lowpass";
      f.frequency.setValueAtTime(cutoff, t);
      f.Q.value = q;
      osc.connect(f);
      node = f;
    }
    node.connect(g);
    g.connect(bus);
    if (delaySend) g.connect(delaySend);
    osc.start(t);
    osc.stop(t + dur + 0.05);
    setTimeout(() => {
      try {
        osc.disconnect();
        g.disconnect();
      } catch {}
    }, (dur + 0.5) * 1000);
  }

  _pad(freq, t, dur, gain) {
    const ctx = this.ctx;
    for (const detune of [-7, 7]) {
      const osc = ctx.createOscillator();
      osc.type = "sawtooth";
      osc.frequency.value = freq;
      osc.detune.value = detune;
      const f = ctx.createBiquadFilter();
      f.type = "lowpass";
      f.frequency.setValueAtTime(500, t);
      f.frequency.linearRampToValueAtTime(1100, t + dur * 0.5);
      f.frequency.linearRampToValueAtTime(420, t + dur);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(gain, t + 0.65);
      g.gain.linearRampToValueAtTime(0.0001, t + dur);
      osc.connect(f);
      f.connect(g);
      g.connect(this.musicBus);
      osc.start(t);
      osc.stop(t + dur + 0.1);
      setTimeout(() => {
        try {
          osc.disconnect();
          g.disconnect();
        } catch {}
      }, (dur + 0.5) * 1000);
    }
  }

  _noise(t, dur, gain, type, freq, bus = this.musicBus, q = 0.8) {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f);
    f.connect(g);
    g.connect(bus);
    src.start(t);
    src.stop(t + dur + 0.02);
    setTimeout(() => {
      try {
        src.disconnect();
        g.disconnect();
      } catch {}
    }, (dur + 0.3) * 1000);
  }

  _kick(t) {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = "sine";
    osc.frequency.setValueAtTime(118, t);
    osc.frequency.exponentialRampToValueAtTime(42, t + 0.16);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.5, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.26);
    osc.connect(g);
    g.connect(this.musicBus);
    osc.start(t);
    osc.stop(t + 0.3);
  }

  _snare(t) {
    this._noise(t, 0.16, 0.18, "highpass", 1400);
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = "triangle";
    osc.frequency.setValueAtTime(190, t);
    osc.frequency.exponentialRampToValueAtTime(120, t + 0.1);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.1, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.12);
    osc.connect(g);
    g.connect(this.musicBus);
    osc.start(t);
    osc.stop(t + 0.14);
  }

  _hat(t, gain) {
    this._noise(t, 0.045, gain, "highpass", 7600);
  }

  scannerPing(vol = 0.5) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    if (pan) {
      pan.pan.setValueAtTime(this.scannerSide * 0.75, t);
      pan.pan.linearRampToValueAtTime(-this.scannerSide * 0.75, t + 0.38);
      this.scannerSide *= -1;
    }
    const osc = ctx.createOscillator();
    osc.type = "triangle";
    osc.frequency.setValueAtTime(720, t);
    osc.frequency.exponentialRampToValueAtTime(1500, t + 0.16);
    osc.frequency.exponentialRampToValueAtTime(520, t + 0.34);
    const f = ctx.createBiquadFilter();
    f.type = "bandpass";
    f.frequency.value = 1100;
    f.Q.value = 1.4;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.075 * vol * 2, t + 0.03);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.42);
    osc.connect(f);
    f.connect(g);
    if (pan) {
      g.connect(pan);
      pan.connect(this.sfxBus);
    } else {
      g.connect(this.sfxBus);
    }
    osc.start(t);
    osc.stop(t + 0.45);
    setTimeout(() => {
      try {
        osc.disconnect();
        g.disconnect();
        pan?.disconnect();
      } catch {}
    }, 900);
  }

  laser() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = "square";
    osc.frequency.setValueAtTime(1800, t);
    osc.frequency.exponentialRampToValueAtTime(220, t + 0.16);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.16, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
    const f = ctx.createBiquadFilter();
    f.type = "lowpass";
    f.frequency.setValueAtTime(4200, t);
    f.frequency.exponentialRampToValueAtTime(500, t + 0.2);
    osc.connect(f);
    f.connect(g);
    g.connect(this.sfxBus);
    osc.start(t);
    osc.stop(t + 0.22);
    this._noise(t, 0.12, 0.12, "highpass", 2200, this.sfxBus);
  }

  crash() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    this._noise(t, 0.5, 0.5, "lowpass", 900, this.sfxBus, 0.6);
    this._noise(t + 0.02, 0.25, 0.3, "bandpass", 1800, this.sfxBus, 1.2);
    const osc = ctx.createOscillator();
    osc.type = "sine";
    osc.frequency.setValueAtTime(110, t);
    osc.frequency.exponentialRampToValueAtTime(38, t + 0.4);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.4, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
    osc.connect(g);
    g.connect(this.sfxBus);
    osc.start(t);
    osc.stop(t + 0.5);
  }

  pickup() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [0, 0.07, 0.14].forEach((delay, i) => {
      this._tone(880 * Math.pow(1.26, i), t + delay, 0.2, "sine", 0.12, this.sfxBus);
    });
  }

  boost() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = "sawtooth";
    osc.frequency.setValueAtTime(120, t);
    osc.frequency.exponentialRampToValueAtTime(900, t + 0.5);
    const f = this.ctx.createBiquadFilter();
    f.type = "lowpass";
    f.frequency.setValueAtTime(400, t);
    f.frequency.linearRampToValueAtTime(2800, t + 0.5);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.11, t + 0.08);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.55);
    osc.connect(f);
    f.connect(g);
    g.connect(this.sfxBus);
    osc.start(t);
    osc.stop(t + 0.6);
    this._noise(t, 0.45, 0.1, "bandpass", 900, this.sfxBus, 0.5);
  }

  jump() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = "triangle";
    osc.frequency.setValueAtTime(260, t);
    osc.frequency.exponentialRampToValueAtTime(1100, t + 0.35);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.14, t + 0.04);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.42);
    osc.connect(g);
    g.connect(this.sfxBus);
    osc.start(t);
    osc.stop(t + 0.45);
  }

  nearMiss() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this._noise(t, 0.25, 0.09, "bandpass", 2400, this.sfxBus, 2.4);
  }

  gameOver() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [0, 0.16, 0.32].forEach((d, i) => this._tone(330 / Math.pow(1.18, i), t + d, 0.6, "sawtooth", 0.06, this.sfxBus, null, 700));
  }

  click() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this._tone(1200, t, 0.05, "square", 0.04, this.sfxBus);
  }
}

import * as THREE from "three";
import { buildKitt, buildTrafficCar, buildEnemyCar, buildDataCore, buildRamp, updateKitt } from "./car.js";
import { LANES, ROAD_HALF } from "./world.js";

const START_TIME = 120;
const BASE_MAX = 96; // ~215 mph
const TURBO_MAX = 134; // ~300 mph
const CAR_X_LIMIT = ROAD_HALF - 1.1;

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = THREE.MathUtils.lerp;
const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));

export class Game {
  constructor(scene, camera, world, effects, audio, callbacks = {}) {
    this.scene = scene;
    this.camera = camera;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.callbacks = callbacks;

    this.mode = "menu";
    this.time = 0;
    this.shake = 0;

    this.kitt = buildKitt();
    this.kitt.group.position.set(LANES[2], 0, 0);
    scene.add(this.kitt.group);

    this.carX = LANES[2];
    this.steer = 0;
    this.speed = 0;
    this.turbo = 100;
    this.shield = 100;
    this.score = 0;
    this.displayScore = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.timeLeft = START_TIME;
    this.distance = 0;
    this.topSpeed = 0;
    this.kills = 0;
    this.cores = 0;
    this.invuln = 0;
    this.jumpY = 0;
    this.jumpV = 0;
    this.airborne = false;
    this.laserCooldown = 0;
    this.boostActive = false;
    this.boostWasOn = false;
    this.elapsed = 0;
    this.trafficTimer = 1.2;
    this.enemyTimer = 6;
    this.coreTimer = 4;
    this.rampTimer = 22;
    this.targetEnemy = null;
    this.ended = false;
    this.endReason = "";

    this.traffic = [];
    this.enemies = [];
    this.coresList = [];
    this.ramps = [];

    this._buildPools();
    this.reset(true);
  }

  _buildPools() {
    const kinds = ["sedan", "suv", "truck", "sedan", "sedan", "suv", "truck", "sedan", "suv", "sedan", "sedan", "suv", "truck", "sedan"];
    for (const kind of kinds) {
      const group = buildTrafficCar(kind);
      group.visible = false;
      this.scene.add(group);
      this.traffic.push({
        group,
        kind,
        active: false,
        x: 0,
        z: -300,
        speed: 30,
        halfW: kind === "truck" ? 1.15 : 1.0,
        halfL: kind === "truck" ? 3.6 : 2.3,
        passed: false,
        scored: false,
      });
    }
    for (let i = 0; i < 5; i++) {
      const e = buildEnemyCar();
      e.group.visible = false;
      this.scene.add(e.group);
      this.enemies.push({
        ...e,
        active: false,
        x: 0,
        z: -300,
        speed: 32,
        lane: 0,
        phase: Math.random() * 10,
        passed: false,
        scored: false,
      });
    }
    for (let i = 0; i < 4; i++) {
      const c = buildDataCore();
      c.group.visible = false;
      this.scene.add(c.group);
      this.coresList.push({ ...c, active: false, x: 0, z: -200, bob: Math.random() * 6 });
    }
    for (let i = 0; i < 2; i++) {
      const group = buildRamp();
      group.visible = false;
      this.scene.add(group);
      this.ramps.push({ group, active: false, x: 0, z: -300 });
    }
  }

  reset(instant = false) {
    this.mode = "menu";
    this.time = 0;
    this.carX = LANES[2];
    this.steer = 0;
    this.speed = 0;
    this.turbo = 100;
    this.shield = 100;
    this.score = 0;
    this.displayScore = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.timeLeft = START_TIME;
    this.distance = 0;
    this.topSpeed = 0;
    this.kills = 0;
    this.cores = 0;
    this.invuln = 0;
    this.jumpY = 0;
    this.jumpV = 0;
    this.airborne = false;
    this.laserCooldown = 0;
    this.boostActive = false;
    this.elapsed = 0;
    this.trafficTimer = 1.6;
    this.enemyTimer = 7;
    this.coreTimer = 3;
    this.rampTimer = 20;
    this.targetEnemy = null;
    this.ended = false;
    this.endReason = "";
    this.shake = 0;

    for (const list of [this.traffic, this.enemies, this.coresList, this.ramps]) {
      for (const e of list) {
        e.active = false;
        e.group.visible = false;
        e.passed = false;
        e.scored = false;
      }
    }
    this.kitt.group.position.set(this.carX, 0, 0);
    this.kitt.group.rotation.set(0, 0, 0);
    this.kitt.group.visible = true;
    void instant;
  }

  startRun() {
    this.reset();
    this.mode = "playing";
    this.speed = 42;
    this.invuln = 2.2;
    this.callbacks.toast?.("K.I.T.T. ONLINE — GO", "gold");
    // seed the highway
    this._spawnTrafficAt(-70, 0.55, 34);
    this._spawnTrafficAt(-130, 2.0, 30);
    this._spawnTrafficAt(-210, 3.0, 37);
    this._spawnTrafficAt(-300, 1.0, 28);
    this._spawnCoreAt(-150, 1.4);
    this._spawnEnemyAt(-260);
    this.audio.setMode("playing");
  }

  pause() {
    if (this.mode === "playing") {
      this.mode = "paused";
      this.audio.setMode("paused");
    }
  }

  resume() {
    if (this.mode === "paused") {
      this.mode = "playing";
      this.audio.setMode("playing");
    }
  }

  endRun(reason) {
    if (this.ended) return;
    this.ended = true;
    this.mode = "over";
    this.endReason = reason;
    this.audio.setMode("menu");
    this.audio.gameOver();
    const stats = this.getStats();
    this.callbacks.gameOver?.(stats);
  }

  getStats() {
    const score = Math.floor(this.score);
    let rank = "D";
    let quote = "“Michael, perhaps we should review the manual.”";
    if (score >= 16000) {
      rank = "S";
      quote = "“Michael, that was almost elegant.”";
    } else if (score >= 10000) {
      rank = "A";
      quote = "“A commendable performance, Michael.”";
    } else if (score >= 6000) {
      rank = "B";
      quote = "“The Foundation will be pleased.”";
    } else if (score >= 3000) {
      rank = "C";
      quote = "“Not bad for a machine.”";
    }
    return {
      score,
      distance: this.distance,
      topSpeed: Math.round(this.topSpeed * 2.23694),
      kills: this.kills,
      cores: this.cores,
      bestCombo: this.bestCombo || 1,
      rank,
      quote,
      reason: this.endReason,
    };
  }

  addScore(base) {
    const mult = 1 + Math.min(this.combo, 12) * 0.25;
    this.score += base * mult;
    return mult;
  }

  bumpCombo() {
    this.combo++;
    this.comboTimer = 4.5;
    this.bestCombo = Math.max(this.bestCombo || 1, 1 + Math.min(this.combo, 12) * 0.25);
  }

  _spawnTrafficAt(z, laneIndex, speed) {
    const e = this.traffic.find((t) => !t.active);
    if (!e) return null;
    const lane = LANES[clamp(Math.round(laneIndex), 0, 3)];
    e.active = true;
    e.passed = false;
    e.scored = false;
    e.z = z;
    e.x = lane + (Math.random() - 0.5) * 0.5;
    e.speed = speed;
    e.group.visible = true;
    e.group.position.set(e.x, 0, e.z);
    return e;
  }

  _spawnTraffic() {
    if (this.traffic.filter((t) => t.active).length >= 11) return;
    const laneIndex = (Math.random() * 4) | 0;
    const lane = LANES[laneIndex];
    for (const t of this.traffic) {
      if (!t.active) continue;
      if (Math.abs(t.x - lane) < 2.6 && t.z < -60 && t.z > -420) return;
    }
    const kindRoll = Math.random();
    let chosen = null;
    for (const t of this.traffic) {
      if (t.active) continue;
      const fits = kindRoll < 0.18 ? t.kind === "truck" : kindRoll < 0.44 ? t.kind === "suv" : t.kind === "sedan";
      if (fits) {
        chosen = t;
        break;
      }
    }
    if (!chosen) chosen = this.traffic.find((t) => !t.active);
    if (!chosen) return;
    const speed = chosen.kind === "truck" ? 23 + Math.random() * 6 : chosen.kind === "suv" ? 27 + Math.random() * 7 : 31 + Math.random() * 8;
    chosen.active = true;
    chosen.passed = false;
    chosen.scored = false;
    chosen.z = -360 - Math.random() * 60;
    chosen.x = lane + (Math.random() - 0.5) * 0.55;
    chosen.speed = speed;
    chosen.group.visible = true;
    chosen.group.position.set(chosen.x, 0, chosen.z);
  }

  _spawnEnemyAt(z) {
    const e = this.enemies.find((x) => !x.active);
    if (!e) return;
    const laneIndex = (Math.random() * 4) | 0;
    e.active = true;
    e.passed = false;
    e.scored = false;
    e.x = LANES[laneIndex];
    e.z = z;
    e.speed = 28 + Math.random() * 8;
    e.phase = Math.random() * 10;
    e.group.visible = true;
    e.group.position.set(e.x, 0, e.z);
  }

  _spawnEnemy() {
    if (this.enemies.filter((e) => e.active).length >= 4) return;
    this._spawnEnemyAt(-380 - Math.random() * 60);
  }

  _spawnCoreAt(z, laneIndex) {
    const c = this.coresList.find((x) => !x.active);
    if (!c) return;
    c.active = true;
    c.z = z;
    c.x = LANES[clamp(Math.round(laneIndex ?? Math.random() * 3), 0, 3)] + (Math.random() - 0.5) * 1.2;
    c.group.visible = true;
    c.group.position.set(c.x, 1.2, c.z);
  }

  _spawnCore() {
    if (this.coresList.filter((c) => c.active).length >= 3) return;
    this._spawnCoreAt(-220 - Math.random() * 180);
  }

  _spawnRamp() {
    const r = this.ramps.find((x) => !x.active);
    if (!r) return;
    r.active = true;
    r.z = -320;
    r.x = LANES[(Math.random() * 4) | 0];
    r.group.visible = true;
    r.group.position.set(r.x, 0.02, r.z);
  }

  _deactivate(e) {
    e.active = false;
    e.group.visible = false;
  }

  fire() {
    if (this.mode !== "playing" || this.laserCooldown > 0) return;
    this.laserCooldown = 0.34;
    this.audio.laser();

    const noseY = 0.78 + this.jumpY;
    let target = null;
    let bestZ = -Infinity;
    for (const e of this.enemies) {
      if (!e.active || e.z > -4 || e.z < -85) continue;
      if (Math.abs(e.x - this.carX) > 6.5) continue;
      if (e.z > bestZ) {
        bestZ = e.z;
        target = e;
      }
    }
    const originL = new THREE.Vector3(this.carX - 0.45, noseY, -2.3);
    const originR = new THREE.Vector3(this.carX + 0.45, noseY, -2.3);
    this.effects.sparks(originL, "#bff6ff");
    this.effects.sparks(originR, "#bff6ff");

    if (target) {
      const to = new THREE.Vector3(target.x, 0.85, target.z + 1.2);
      this.effects.laser(originL, to);
      this.effects.laser(originR, to);
      this.effects.explosion(new THREE.Vector3(target.x, 1.0, target.z));
      this.effects.shockwave(new THREE.Vector3(target.x, 0.3, target.z), "#ff8a2a", 8, 0.5);
      this.audio.crash();
      this.kills++;
      this.bumpCombo();
      const mult = this.addScore(300);
      this.turbo = Math.min(100, this.turbo + 16);
      this.callbacks.toast?.(`INTERCEPTOR DOWN  +${Math.round(300 * mult)}`, "gold");
      this.shake = Math.max(this.shake, 0.35);
      this._deactivate(target);
      this.targetEnemy = null;
    } else {
      const to = new THREE.Vector3(this.carX + (Math.random() - 0.5) * 1.2, noseY - 0.08, -70);
      this.effects.laser(originL, to.clone().setX(this.carX - 0.5));
      this.effects.laser(originR, to.clone().setX(this.carX + 0.5));
      this.effects.sparks(to, "#9ff4ff");
    }
  }

  _hitVehicle(vehicle, isEnemy) {
    if (this.invuln > 0 || this.airborne) return;
    const pos = new THREE.Vector3((this.carX + vehicle.x) / 2, 0.9, (vehicle.z + 0) / 2);
    const ramming = this.boostActive && this.speed > 105 && !isEnemy;
    this.invuln = 1.4;
    this.shake = 1.2;
    this.audio.crash();
    this.effects.explosion(pos);
    this.effects.shockwave(new THREE.Vector3(vehicle.x, 0.25, vehicle.z), "#ff5a3c", 6, 0.45);
    this.combo = 0;
    this.comboTimer = 0;

    if (ramming) {
      this.shield = Math.max(0, this.shield - 12);
      this.speed *= 0.9;
      this.score += 250;
      this.callbacks.toast?.("TURBO RAM  +250", "cyan");
      this.callbacks.hit?.(0.35);
    } else {
      const dmg = isEnemy ? 34 : 28;
      this.shield = Math.max(0, this.shield - dmg);
      this.speed *= 0.52;
      this.callbacks.toast?.(`SHELL IMPACT  −${dmg}%`, "red");
      this.callbacks.hit?.(1);
    }
    this._deactivate(vehicle);
    if (this.shield <= 0) this.endRun("disabled");
  }

  _nearMiss(vehicle) {
    if (vehicle.scored) return;
    vehicle.scored = true;
    const dist = Math.abs(vehicle.x - this.carX);
    if (dist > 3.4 || dist < 1.95) return;
    this.bumpCombo();
    const mult = this.addScore(120);
    this.turbo = Math.min(100, this.turbo + 4.5);
    this.audio.nearMiss();
    if (this.combo === 1 || this.combo % 3 === 0) {
      this.callbacks.toast?.(`NEAR MISS  ×${mult.toFixed(2)}`, "cyan");
    }
  }

  update(dt, input) {
    this.time += dt;
    this.laserCooldown = Math.max(0, this.laserCooldown - dt);
    this.shake = Math.max(0, this.shake - dt * 2.4);
    this.invuln = Math.max(0, this.invuln - dt);

    if (this.mode === "menu") {
      this.world.update(dt, 12 + Math.sin(this.time * 0.4) * 2);
      this.speed = 8;
      this.kitt.group.position.set(this.carX, 0, 0);
      this.steer = Math.sin(this.time * 0.3) * 0.06;
      updateKitt(this.kitt, dt, { speed: 8, steer: this.steer, time: this.time });
      this.kitt.group.rotation.y = damp(this.kitt.group.rotation.y, -this.steer * 0.04, 3, dt);
      this.targetEnemy = null;
      return;
    }

    if (this.mode === "paused") {
      updateKitt(this.kitt, dt * 0.15, { speed: 0, steer: this.steer, time: this.time });
      return;
    }

    if (this.mode === "over") {
      this.speed = damp(this.speed, 0, 1.1, dt);
      this.world.update(dt, this.speed);
      this.kitt.group.position.set(this.carX, this.jumpY, 0);
      updateKitt(this.kitt, dt, { speed: this.speed, steer: this.steer, time: this.time, braking: true });
      this._updateEntities(dt, speedDt(this.speed, dt));
      this._updateCamera(dt);
      return;
    }

    // ---------------- playing ----------------
    this.elapsed += dt;
    this.timeLeft -= dt;
    if (this.timeLeft <= 0) {
      this.timeLeft = 0;
      this.endRun("time");
      return;
    }

    this.comboTimer -= dt;
    if (this.comboTimer <= 0 && this.combo > 0) this.combo = 0;

    // throttle / brake
    const throttle = input.throttle || input.boost;
    this.boostActive = !!input.boost && this.turbo > 1 && this.speed > 4;
    if (this.boostActive) {
      this.turbo = Math.max(0, this.turbo - 23 * dt);
      this.speed += 38 * dt;
      if (!this.boostWasOn) {
        this.audio.boost();
        this.callbacks.toast?.("TURBO BOOST", "cyan");
        this.shake = Math.max(this.shake, 0.4);
      }
      this.boostWasOn = true;
    } else {
      this.boostWasOn = false;
      this.turbo = Math.min(100, this.turbo + 4.2 * dt);
      if (throttle) this.speed += 17 * dt;
      if (input.brake) this.speed -= 44 * dt;
      else if (!throttle) this.speed -= 7 * dt;
      if (this.speed > BASE_MAX) this.speed = Math.max(BASE_MAX, this.speed - 12 * dt);
    }
    this.speed = clamp(this.speed, 0, this.boostActive ? TURBO_MAX : Math.max(BASE_MAX, this.speed));

    // steering
    const steerTarget = input.steer || 0;
    this.steer = damp(this.steer, steerTarget, 9, dt);
    const lateralSpeed = 8 + this.speed * 0.036;
    this.carX += this.steer * lateralSpeed * dt;
    if (this.carX < -CAR_X_LIMIT) {
      this.carX = -CAR_X_LIMIT;
      this.steer *= 0.4;
      this.shake = Math.max(this.shake, 0.1);
    }
    if (this.carX > CAR_X_LIMIT) {
      this.carX = CAR_X_LIMIT;
      this.steer *= 0.4;
      this.shake = Math.max(this.shake, 0.1);
    }

    // jump physics
    if (this.airborne) {
      this.jumpY += this.jumpV * dt;
      this.jumpV -= 30 * dt;
      if (this.jumpY <= 0) {
        this.jumpY = 0;
        this.jumpV = 0;
        this.airborne = false;
        this.shake = Math.max(this.shake, 0.5);
        this.effects.sparks(new THREE.Vector3(this.carX, 0.2, 1.8), "#ffb648");
        this.audio.crash();
      }
    }

    this.distance += this.speed * dt;
    this.topSpeed = Math.max(this.topSpeed, this.speed);
    this.score += this.speed * dt * 0.28;

    // entities
    const scroll = speedDt(this.speed, dt);
    this._updateEntities(dt, scroll);

    // spawns
    this.trafficTimer -= dt;
    if (this.trafficTimer <= 0) {
      this.trafficTimer = Math.max(0.58, 1.55 - this.elapsed * 0.012);
      this._spawnTraffic();
    }
    this.enemyTimer -= dt;
    if (this.enemyTimer <= 0) {
      this.enemyTimer = Math.max(3.6, 8.5 - this.elapsed * 0.05);
      this._spawnEnemy();
    }
    this.coreTimer -= dt;
    if (this.coreTimer <= 0) {
      this.coreTimer = 6.5 + Math.random() * 3;
      this._spawnCore();
    }
    this.rampTimer -= dt;
    if (this.rampTimer <= 0) {
      this.rampTimer = 22 + Math.random() * 14;
      this._spawnRamp();
    }

    if (input.fire) this.fire();

    // visuals
    this.kitt.group.position.set(this.carX, this.jumpY, 0);
    this.kitt.group.rotation.y = damp(this.kitt.group.rotation.y, -this.steer * 0.075, 7, dt);
    updateKitt(this.kitt, dt, {
      speed: this.speed,
      steer: this.steer,
      braking: !!input.brake,
      boost: this.boostActive,
      time: this.time,
      airborne: this.airborne,
    });

    // exhaust trail
    if (this.boostActive) {
      const rear = new THREE.Vector3(this.carX + (Math.random() - 0.5) * 1.1, 0.45 + this.jumpY, 2.45);
      this.effects.trail(rear, new THREE.Color("#ff7a22"), 0.5, 7);
      this.effects.trail(rear, new THREE.Color("#7fe8ff"), 0.3, 4);
    }

    // target lock
    let target = null;
    let best = -Infinity;
    for (const e of this.enemies) {
      if (!e.active || e.z > -4 || e.z < -85) continue;
      if (Math.abs(e.x - this.carX) > 6.5) continue;
      if (e.z > best) {
        best = e.z;
        target = e;
      }
    }
    this.targetEnemy = target;
    this._updateCamera(dt);
  }

  _updateEntities(dt, scroll) {
    const scrollStatic = scroll;
    for (const t of this.traffic) {
      if (!t.active) continue;
      t.z += scroll - t.speed * dt;
      t.group.position.set(t.x, 0, t.z);
      if (t.z > 1.5 && !t.passed) {
        t.passed = true;
        this._nearMiss(t);
      }
      if (Math.abs(t.z) < 3.9 && !t.scored && Math.abs(t.x - this.carX) < 1.2 + t.halfW - 0.35) {
        t.scored = true;
        this._hitVehicle(t, false);
      }
      if (t.z > 32) this._deactivate(t);
    }

    for (const e of this.enemies) {
      if (!e.active) continue;
      e.z += scroll - e.speed * dt;
      e.phase += dt * 1.8;
      const targetX = e.x + Math.sin(e.phase) * 0.9;
      e.group.position.set(targetX, 0, e.z);
      e.group.rotation.z = Math.sin(e.phase * 0.7) * 0.03;
      const blink = Math.sin(this.time * 11 + e.phase) > 0;
      e.redLight.visible = blink;
      e.blueLight.visible = !blink;
      e.lightGlow.material.color.set(blink ? "#ff2038" : "#2a6bff");
      if (e.z > 1.5 && !e.passed) {
        e.passed = true;
        this._nearMiss(e);
      }
      if (Math.abs(e.z) < 4.1 && !e.scored && Math.abs(targetX - this.carX) < 1.95) {
        e.scored = true;
        this._hitVehicle(e, true);
      }
      if (e.z > 32) this._deactivate(e);
    }

    for (const c of this.coresList) {
      if (!c.active) continue;
      c.z += scrollStatic;
      c.bob += dt * 2;
      c.group.position.set(c.x, 1.25 + Math.sin(c.bob) * 0.22, c.z);
      c.group.rotation.y += dt * 1.6;
      c.ring2.rotation.z += dt * 2.2;
      c.core.rotation.x += dt * 1.1;
      c.core.rotation.y += dt * 0.8;
      if (Math.abs(c.z) < 3.2 && Math.abs(c.x - this.carX) < 2.3 && !this.airborne) {
        this._deactivate(c);
        this.cores++;
        this.bumpCombo();
        this.timeLeft = Math.min(999, this.timeLeft + 7);
        this.shield = Math.min(100, this.shield + 10);
        this.turbo = Math.min(100, this.turbo + 30);
        const mult = this.addScore(200);
        this.audio.pickup();
        this.effects.pickup(new THREE.Vector3(c.x, 1.2, c.z));
        this.callbacks.toast?.(`DATA CORE  +7s  +${Math.round(200 * mult)}`, "gold");
      }
      if (c.z > 30) this._deactivate(c);
    }

    for (const r of this.ramps) {
      if (!r.active) continue;
      r.z += scrollStatic;
      r.group.position.set(r.x, 0.02, r.z);
      if (Math.abs(r.z) < 3.2 && Math.abs(r.x - this.carX) < 2.0 && !this.airborne) {
        this.airborne = true;
        this.jumpV = 11.5;
        this.jumpY = 0.15;
        this.audio.jump();
        this.shake = Math.max(this.shake, 0.45);
        this.callbacks.toast?.("TURBO JUMP", "cyan");
        this.effects.sparks(new THREE.Vector3(this.carX, 0.4, 2), "#7fe8ff");
      }
      if (r.z > 25) this._deactivate(r);
    }
  }

  _updateCamera(dt) {
    if (this.mode === "menu") {
      const a = 0.72 + Math.sin(this.time * 0.1) * 0.16;
      const cx = this.carX - 5.4 * Math.cos(a);
      const cz = -2.2 - 7.2 * Math.sin(a);
      this.camera.position.set(cx, 2.0 + Math.sin(this.time * 0.27) * 0.12, cz);
      this.camera.lookAt(this.carX - 2.7, 0.78, 0.4);
      if (Math.abs(this.camera.fov - 52) > 0.01) {
        this.camera.fov = damp(this.camera.fov, 52, 4, dt);
        this.camera.updateProjectionMatrix();
      }
      return;
    }

    const speedNorm = clamp(this.speed / TURBO_MAX, 0, 1);
    const jumpLift = this.jumpY * 0.55;
    const desired = new THREE.Vector3(
      this.carX * 0.8,
      3.55 + jumpLift + speedNorm * 0.55,
      8.4 + speedNorm * 2.4
    );
    const k = 1 - Math.exp(-5.2 * dt);
    this.camera.position.lerp(desired, k);
    const look = new THREE.Vector3(
      this.carX * 0.62,
      1.0 + this.jumpY * 0.8,
      -7 - speedNorm * 5
    );
    this.camera.lookAt(look);
    const targetFov = 61 + speedNorm * 11 + (this.boostActive ? 5 : 0);
    this.camera.fov = damp(this.camera.fov, targetFov, 3.6, dt);
    this.camera.updateProjectionMatrix();

    if (this.shake > 0.001) {
      const s = this.shake;
      this.camera.position.x += (Math.random() - 0.5) * 0.42 * s;
      this.camera.position.y += (Math.random() - 0.5) * 0.3 * s;
      this.camera.rotateZ((Math.random() - 0.5) * 0.02 * s);
    }
  }

  getHud() {
    return {
      mode: this.mode,
      speedMph: Math.round(this.speed * 2.23694),
      speedNorm: clamp(this.speed / TURBO_MAX, 0, 1),
      score: Math.floor(this.score),
      timer: Math.max(0, this.timeLeft),
      distance: this.distance / 1609.34,
      shield: this.shield,
      turbo: this.turbo,
      combo: this.combo,
      multiplier: 1 + Math.min(this.combo, 12) * 0.25,
      kills: this.kills,
      cores: this.cores,
      topSpeed: Math.round(this.topSpeed * 2.23694),
      target: this.targetEnemy ? this.targetEnemy.group.position : null,
      laserCooldown: this.laserCooldown,
      boostActive: this.boostActive,
      airborne: this.airborne,
      invuln: this.invuln,
    };
  }
}

function speedDt(speed, dt) {
  return speed * dt;
}

