500: export function updateKitt(kitt, dt, { speed = 0, steer = 0, braking = false, boost = false, time = 0, airborne = false }) {
501:   const speedNorm = Math.min(1, Math.abs(speed) / 90);
502:   for (const w of kitt.wheels) {
503:     w.mesh.rotation.x -= (speed * dt) / 0.35;
504:   }
505:   for (const p of kitt.frontSteer) {
506:     p.rotation.y = THREE.MathUtils.lerp(p.rotation.y, steer * 0.34, 1 - Math.pow(0.001, dt));
507:   }
508:   // Body attitude
509:   const roll = -steer * 0.045 * (0.4 + speedNorm);
510:   kitt.group.rotation.z = THREE.MathUtils.lerp(kitt.group.rotation.z, roll, 1 - Math.pow(0.002, dt));
511:   kitt.group.rotation.x = THREE.MathUtils.lerp(
512:     kitt.group.rotation.x,
513:     airborne ? -0.12 : boost ? 0.022 : braking ? -0.02 : 0.004,
514:     1 - Math.pow(0.005, dt)
515:   );
516: 
517:   // Scanner bounce: 0..1..0 triangular wave, smoothed
518:   const period = 1.15;
519:   const raw = (time % period) / period;
520:   const tri = raw < 0.5 ? raw * 2 : (1 - raw) * 2;
521:   const pos = tri * 7;
522:   let strongest = 0;
523:   for (let i = 0; i < kitt.segments.length; i++) {
524:     const d = Math.abs(i - pos);
525:     const v = Math.max(0, 1 - d / 1.7);
526:     const intensity = Math.pow(v, 1.6);
527:     strongest = Math.max(strongest, intensity);
528:     const mat = kitt.segments[i].material;
529:     mat.color.setRGB(1, 0.03 + 0.14 * intensity, 0.06 + 0.12 * intensity);
530:   }
531:   kitt.scannerGlow.material.opacity = 0.26 + strongest * 0.55;
532:   kitt.scannerGlow.material.color.setRGB(1, 0.1 + 0.1 * strongest, 0.15);
533:   kitt.scannerLight.intensity = 1.5 + strongest * 8;
534: 
535:   // Brake lights
536:   for (const bar of kitt.brakeBars) bar.material.color.set(braking ? "#ff2334" : "#8e0712");
537:   for (const glow of kitt.brakeGlows) glow.material.opacity = braking ? 0.7 : 0.32;
538: 
539:   // Exhaust
540:   const flame = boost && !airborne;
541:   for (const f of kitt.exhaust.children) {
542:     f.material.opacity = flame ? 0.75 + Math.sin(time * 55 + f.position.x * 9) * 0.22 : 0;
543:     f.scale.set(1, 0.7 + Math.random() * 0.8, 1);
544:   }
545: }
