353:   fire() {
354:     if (this.mode !== "playing" || this.laserCooldown > 0) return;
355:     this.laserCooldown = 0.34;
356:     this.audio.laser();
357: 
358:     const noseY = 0.78 + this.jumpY;
359:     let target = null;
360:     let bestZ = -Infinity;
361:     for (const e of this.enemies) {
362:       if (!e.active || e.z > -4 || e.z < -85) continue;
363:       if (Math.abs(e.x - this.carX) > 6.5) continue;
364:       if (e.z > bestZ) {
365:         bestZ = e.z;
366:         target = e;
367:       }
368:     }
369:     const originL = new THREE.Vector3(this.carX - 0.45, noseY, -2.3);
370:     const originR = new THREE.Vector3(this.carX + 0.45, noseY, -2.3);
371:     this.effects.sparks(originL, "#bff6ff");
372:     this.effects.sparks(originR, "#bff6ff");
373: 
374:     if (target) {
375:       const to = new THREE.Vector3(target.x, 0.85, target.z + 1.2);
376:       this.effects.laser(originL, to);
377:       this.effects.laser(originR, to);
378:       this.effects.explosion(new THREE.Vector3(target.x, 1.0, target.z));
379:       this.effects.shockwave(new THREE.Vector3(target.x, 0.3, target.z), "#ff8a2a", 8, 0.5);
380:       this.audio.crash();
381:       this.kills++;
382:       this.bumpCombo();
383:       const mult = this.addScore(300);
384:       this.turbo = Math.min(100, this.turbo + 16);
385:       this.callbacks.toast?.(`INTERCEPTOR DOWN  +${Math.round(300 * mult)}`, "gold");
386:       this.shake = Math.max(this.shake, 0.35);
387:       this._deactivate(target);
388:       this.targetEnemy = null;
389:     } else {
390:       const to = new THREE.Vector3(this.carX + (Math.random() - 0.5) * 1.2, noseY - 0.08, -70);
391:       this.effects.laser(originL, to.clone().setX(this.carX - 0.5));
392:       this.effects.laser(originR, to.clone().setX(this.carX + 0.5));
393:       this.effects.sparks(to, "#9ff4ff");
394:     }
395:   }
