397:   _hitVehicle(vehicle, isEnemy) {
398:     if (this.invuln > 0 || this.airborne) return;
399:     const pos = new THREE.Vector3((this.carX + vehicle.x) / 2, 0.9, (vehicle.z + 0) / 2);
400:     const ramming = this.boostActive && this.speed > 105 && !isEnemy;
401:     this.invuln = 1.4;
402:     this.shake = 1.2;
403:     this.audio.crash();
404:     this.effects.explosion(pos);
405:     this.effects.shockwave(new THREE.Vector3(vehicle.x, 0.25, vehicle.z), "#ff5a3c", 6, 0.45);
406:     this.combo = 0;
407:     this.comboTimer = 0;
408: 
409:     if (ramming) {
410:       this.shield = Math.max(0, this.shield - 12);
411:       this.speed *= 0.9;
412:       this.score += 250;
413:       this.callbacks.toast?.("TURBO RAM  +250", "cyan");
414:       this.callbacks.hit?.(0.35);
415:     } else {
416:       const dmg = isEnemy ? 34 : 28;
417:       this.shield = Math.max(0, this.shield - dmg);
418:       this.speed *= 0.52;
419:       this.callbacks.toast?.(`SHELL IMPACT  −${dmg}%`, "red");
420:       this.callbacks.hit?.(1);
421:     }
422:     this._deactivate(vehicle);
423:     if (this.shield <= 0) this.endRun("disabled");
424:   }
