426:   _nearMiss(vehicle) {
427:     if (vehicle.scored) return;
428:     vehicle.scored = true;
429:     const dist = Math.abs((vehicle.group?.position.x ?? vehicle.x) - this.carX);
430:     if (dist > 3.4 || dist < 1.95) return;
431:     this.bumpCombo();
432:     const mult = this.addScore(120);
433:     this.turbo = Math.min(100, this.turbo + 4.5);
434:     this.audio.nearMiss();
435:     if (this.combo === 1 || this.combo % 3 === 0) {
436:       this.callbacks.toast?.(`NEAR MISS  ×${mult.toFixed(2)}`, "cyan");
437:     }
438:   }
