440:   update(dt, input) {
441:     this.time += dt;
442:     this.laserCooldown = Math.max(0, this.laserCooldown - dt);
443:     this.shake = Math.max(0, this.shake - dt * 2.4);
444:     this.invuln = Math.max(0, this.invuln - dt);
445: 
446:     if (this.mode === "menu") {
447:       this.world.update(dt, 12 + Math.sin(this.time * 0.4) * 2);
448:       this.speed = 8;
449:       this.kitt.group.position.set(this.carX, 0, 0);
450:       this.steer = Math.sin(this.time * 0.3) * 0.06;
451:       updateKitt(this.kitt, dt, { speed: 8, steer: this.steer, time: this.time });
452:       this.kitt.group.rotation.y = damp(this.kitt.group.rotation.y, -this.steer * 0.04, 3, dt);
453:       this.targetEnemy = null;
454:       this._updateCamera(dt);
455:       return;
456:     }
457: 
458:     if (this.mode === "paused") {
459:       updateKitt(this.kitt, dt * 0.15, { speed: 0, steer: this.steer, time: this.time });
460:       return;
461:     }
462: 
463:     if (this.mode === "over") {
464:       this.speed = damp(this.speed, 0, 1.1, dt);
465:       this.world.update(dt, this.speed);
466:       this.kitt.group.position.set(this.carX, this.jumpY, 0);
467:       updateKitt(this.kitt, dt, { speed: this.speed, steer: this.steer, time: this.time, braking: true });
468:       this._updateCamera(dt);
469:       return;
470:     }
471: 
472:     // ---------------- playing ----------------
473:     this.elapsed += dt;
474:     this.timeLeft -= dt;
475:     if (this.timeLeft <= 0) {
476:       this.timeLeft = 0;
477:       this.endRun("time");
478:       return;
479:     }
480: 
481:     this.comboTimer -= dt;
482:     if (this.comboTimer <= 0 && this.combo > 0) this.combo = 0;
483: 
484:     // throttle / brake
485:     const throttle = input.throttle || input.boost;
486:     this.boostActive = !!input.boost && this.turbo > 1 && this.speed > 4;
487:     if (this.boostActive) {
488:       this.turbo = Math.max(0, this.turbo - 23 * dt);
489:       this.speed += 38 * dt;
490:       if (!this.boostWasOn) {
491:         this.audio.boost();
492:         this.callbacks.toast?.("TURBO BOOST", "cyan");
493:         this.shake = Math.max(this.shake, 0.4);
494:       }
495:       this.boostWasOn = true;
496:     } else {
497:       this.boostWasOn = false;
498:       this.turbo = Math.min(100, this.turbo + 4.2 * dt);
499:       if (throttle) this.speed += 17 * dt;
500:       if (input.brake) this.speed -= 44 * dt;
501:       else if (!throttle) this.speed -= 7 * dt;
502:       if (this.speed > BASE_MAX) this.speed = Math.max(BASE_MAX, this.speed - 12 * dt);
503:     }
504:     this.speed = clamp(this.speed, 0, this.boostActive ? TURBO_MAX : Math.max(BASE_MAX, this.speed));
505: 
506:     // steering
507:     const steerTarget = input.steer || 0;
508:     this.steer = damp(this.steer, steerTarget, 9, dt);
509:     const lateralSpeed = 8 + this.speed * 0.036;
510:     this.carX += this.steer * lateralSpeed * dt;
511:     if (this.carX < -CAR_X_LIMIT) {
512:       this.carX = -CAR_X_LIMIT;
513:       this.steer *= 0.4;
514:       this.shake = Math.max(this.shake, 0.1);
515:     }
516:     if (this.carX > CAR_X_LIMIT) {
517:       this.carX = CAR_X_LIMIT;
518:       this.steer *= 0.4;
519:       this.shake = Math.max(this.shake, 0.1);
520:     }
521: 
522:     // jump physics
523:     if (this.airborne) {
524:       this.jumpY += this.jumpV * dt;
525:       this.jumpV -= 30 * dt;
526:       if (this.jumpY <= 0) {
527:         this.jumpY = 0;
528:         this.jumpV = 0;
529:         this.airborne = false;
530:         this.shake = Math.max(this.shake, 0.5);
531:         this.effects.sparks(new THREE.Vector3(this.carX, 0.2, 1.8), "#ffb648");
532:         this.audio.crash();
533:       }
534:     }
535: 
536:     this.distance += this.speed * dt;
537:     this.topSpeed = Math.max(this.topSpeed, this.speed);
538:     this.score += this.speed * dt * 0.28;
539: 
540:     // entities
541:     const scroll = speedDt(this.speed, dt);
542:     this._updateEntities(dt, scroll);
543: 
544:     // spawns
545:     this.trafficTimer -= dt;
546:     if (this.trafficTimer <= 0) {
547:       this.trafficTimer = Math.max(0.58, 1.55 - this.elapsed * 0.012);
548:       this._spawnTraffic();
549:     }
550:     this.enemyTimer -= dt;
551:     if (this.enemyTimer <= 0) {
552:       this.enemyTimer = Math.max(3.6, 8.5 - this.elapsed * 0.05);
553:       this._spawnEnemy();
554:     }
555:     this.coreTimer -= dt;
556:     if (this.coreTimer <= 0) {
557:       this.coreTimer = 6.5 + Math.random() * 3;
558:       this._spawnCore();
559:     }
560:     this.rampTimer -= dt;
561:     if (this.rampTimer <= 0) {
562:       this.rampTimer = 22 + Math.random() * 14;
563:       this._spawnRamp();
564:     }
565: 
566:     if (input.fire) this.fire();
567: 
568:     // visuals
569:     this.kitt.group.position.set(this.carX, this.jumpY, 0);
570:     this.kitt.group.rotation.y = damp(this.kitt.group.rotation.y, -this.steer * 0.075, 7, dt);
571:     updateKitt(this.kitt, dt, {
572:       speed: this.speed,
573:       steer: this.steer,
574:       braking: !!input.brake,
575:       boost: this.boostActive,
576:       time: this.time,
577:       airborne: this.airborne,
578:     });
579: 
580:     // exhaust trail
581:     if (this.boostActive) {
582:       const rear = new THREE.Vector3(this.carX + (Math.random() - 0.5) * 1.1, 0.45 + this.jumpY, 2.45);
583:       this.effects.trail(rear, new THREE.Color("#ff7a22"), 0.5, 7);
584:       this.effects.trail(rear, new THREE.Color("#7fe8ff"), 0.3, 4);
585:     }
586: 
587:     // target lock
588:     let target = null;
589:     let best = -Infinity;
590:     for (const e of this.enemies) {
591:       if (!e.active || e.z > -4 || e.z < -85) continue;
592:       if (Math.abs(e.x - this.carX) > 6.5) continue;
593:       if (e.z > best) {
594:         best = e.z;
595:         target = e;
596:       }
597:     }
598:     this.targetEnemy = target;
599:     this._updateCamera(dt);
600:   }
601: 
602:   _updateEntities(dt, scroll) {
603:     const scrollStatic = scroll;
604:     for (const t of this.traffic) {
605:       if (!t.active) continue;
606:       t.z += scroll - t.speed * dt;
607:       t.group.position.set(t.x, 0, t.z);
608:       if (t.z > 1.5 && !t.passed) {
609:         t.passed = true;
610:         this._nearMiss(t);
611:       }
612:       if (Math.abs(t.z) < 3.9 && !t.collided && Math.abs(t.x - this.carX) < 1.2 + t.halfW - 0.35) {
613:         t.collided = true;
614:         t.scored = true;
615:         this._hitVehicle(t, false);
616:       }
617:       if (t.z > 32) this._deactivate(t);
618:     }
619: 
620:     for (const e of this.enemies) {
621:       if (!e.active) continue;
