function wheel(r = 0.35, width = 0.3) {
  const g = new THREE.Group();
  const tireMat = new THREE.MeshStandardMaterial({ color: "#08090c", roughness: 0.94, metalness: 0.02 });
  const rimMat = new THREE.MeshStandardMaterial({ color: "#9aa3b3", roughness: 0.28, metalness: 0.95 });
  const darkMat = new THREE.MeshStandardMaterial({ color: "#15171d", roughness: 0.55, metalness: 0.6 });

  const tire = new THREE.Mesh(new THREE.CylinderGeometry(r, r, width, 26), tireMat);
  tire.rotation.z = Math.PI / 2;
  g.add(tire);

  // tire sidewall shading rings
  for (const side of [-1, 1]) {
    const wall = new THREE.Mesh(new THREE.TorusGeometry(r * 0.9, r * 0.09, 6, 26), tireMat);
    wall.rotation.y = Math.PI / 2;
    wall.position.x = side * width * 0.5;
    g.add(wall);

    const ring = new THREE.Mesh(new THREE.TorusGeometry(r * 0.58, r * 0.045, 6, 24), rimMat);
    ring.rotation.y = Math.PI / 2;
    ring.position.x = side * (width * 0.5 + 0.012);
    g.add(ring);

    const hub = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.15, r * 0.15, width * 0.36, 12), rimMat);
    hub.rotation.z = Math.PI / 2;
    hub.position.x = side * (width * 0.5 + 0.01);
    g.add(hub);

    for (let i = 0; i < 5; i++) {
      const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.028, r * 0.78, r * 0.09), rimMat);
      spoke.position.x = side * (width * 0.5 + 0.006);
      spoke.rotation.x = (i / 5) * Math.PI * 2;
      g.add(spoke);
    }
  }

  const brake = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.44, r * 0.44, width * 0.3, 18), darkMat);
  brake.rotation.z = Math.PI / 2;
  g.add(brake);
  return g;
}

