        mat.color = new Color(0f, 0f, 0f, alpha);
        GameObject go = MeshUtils.MakeMeshObject("Shadow", MeshUtils.Quad(w, l), mat, parent);
        go.transform.localPosition = pos;
        go.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
        return go;
    }

