using UnityEngine;

namespace KnightRider3D
{
    public class TrafficVehicle
    {
        public GameObject Go;
        public bool Active;
        public bool Passed;
        public bool Scored;
        public bool Collided;
        public float X;
        public float Z;
        public float Speed;
        public float HalfW;
        public float HalfL;
        public string Kind;
    }

    public class EnemyVehicle
    {
        public GameObject Go;
        public bool Active;
        public bool Passed;
        public bool Scored;
        public bool Collided;
        public float X;
        public float Z;
        public float Speed;
        public float Phase;
        public GameObject RedLight;
        public GameObject BlueLight;
        public SpriteRenderer Glow;
    }

    public class DataCore
    {
        public GameObject Go;
        public bool Active;
        public float X;
        public float Z;
        public float Bob;
        public Transform Core;
        public Transform Ring1;
        public Transform Ring2;
    }

    public class Ramp
    {
        public GameObject Go;
        public bool Active;
        public float X;
        public float Z;
    }

    public static class VehicleFactory
    {
        private static readonly Color[] TrafficColors =
        {
            new Color(0.55f, 0.13f, 0.19f),
            new Color(0.16f, 0.25f, 0.40f),
            new Color(0.74f, 0.72f, 0.68f),
            new Color(0.24f, 0.25f, 0.28f),
            new Color(0.35f, 0.40f, 0.47f),
            new Color(0.49f, 0.23f, 0.15f),
            new Color(0.14f, 0.30f, 0.29f),
            new Color(0.62f, 0.58f, 0.51f)
        };

        public static TrafficVehicle BuildTraffic(string kind)
        {
            TrafficVehicle vehicle = new TrafficVehicle();
            vehicle.Kind = kind;
            vehicle.HalfW = kind == "truck" ? 1.15f : 1.0f;
            vehicle.HalfL = kind == "truck" ? 3.6f : 2.3f;
            GameObject group = new GameObject("Traffic_" + kind);
            vehicle.Go = group;
            Transform root = group.transform;

            Color paint = TrafficColors[Random.Range(0, TrafficColors.Length)];
            Material paintMat = GameMaterials.Paint(paint);
            Material glassMat = GameMaterials.Glass;
            Material trimMat = GameMaterials.Trim;

            if (kind == "truck")
            {
                MeshUtils.Box(root, "Box", new Vector3(0f, 1.45f, 0f),
                    new Vector3(2.2f, 2.1f, 5.4f), paintMat);
                MeshUtils.Box(root, "Cab", new Vector3(0f, 1.06f, -3.1f),
                    new Vector3(2.15f, 1.35f, 1.7f), paintMat);
                MeshUtils.Box(root, "Windshield", new Vector3(0f, 1.35f, -3.96f),
                    new Vector3(1.9f, 0.62f, 0.05f), glassMat);
                MeshUtils.Box(root, "Chassis", new Vector3(0f, 0.45f, 0f),
                    new Vector3(2.0f, 0.35f, 6.6f), trimMat);
                for (int z = -1; z <= 1; z += 2)
                {
                    for (int x = -1; x <= 1; x += 2)
                    {
                        GameObject pivot = new GameObject("Wheel");
                        pivot.transform.SetParent(root, false);
                        pivot.transform.localPosition = new Vector3(x * 0.92f, 0.46f, z * 2.25f);
                        KittCar.BuildWheel(pivot.transform, 0.46f, 0.30f, false);
                    }
                }
            }
            else if (kind == "suv")
            {
                MeshUtils.Box(root, "Body", new Vector3(0f, 0.66f, 0f),
                    new Vector3(1.98f, 0.72f, 4.5f), paintMat);
                MeshUtils.MakeMeshObject("Cabin", MeshUtils.Cabin(1.84f, 0.64f, 2.7f),
                    glassMat, root).transform.localPosition = new Vector3(0f, 1.24f, 0.28f);
                MeshUtils.Box(root, "Roof", new Vector3(0f, 1.56f, 0.36f),
                    new Vector3(1.66f, 0.08f, 2.2f), paintMat);
                AddWheels(root, 1.45f, 0.40f);
            }
            else
            {
                MeshUtils.MakeMeshObject("Body", MeshUtils.Wedge(1.92f, 0.56f, 4.3f, 0.2f),
                    paintMat, root).transform.localPosition = new Vector3(0f, 0.56f, 0f);
                MeshUtils.MakeMeshObject("Cabin", MeshUtils.Cabin(1.66f, 0.52f, 1.95f),
                    glassMat, root).transform.localPosition = new Vector3(0f, 1.02f, 0.15f);
                AddWheels(root, 1.4f, 0.34f);
            }

            float rearZ = kind == "truck" ? 2.72f : kind == "suv" ? 2.27f : 2.16f;
            for (int side = -1; side <= 1; side += 2)
            {
                MeshUtils.Box(root, "Tail", new Vector3(side * (kind == "truck" ? 0.84f : 0.66f),
                        kind == "truck" ? 1.0f : 0.66f, rearZ),
                    new Vector3(0.34f, 0.12f, 0.03f), GameMaterials.Tail);
                Visuals.GlowSprite(root, "TailGlow",
                    new Vector3(side * (kind == "truck" ? 0.84f : 0.66f),
                        kind == "truck" ? 1.0f : 0.66f, rearZ + 0.04f),
                    Palette.Red, 0.40f, 0.45f);
                MeshUtils.Box(root, "Head", new Vector3(side * 0.62f, 0.62f, kind == "truck" ? -3.97f : -2.15f),
                    new Vector3(0.36f, 0.10f, 0.02f), GameMaterials.Headlight);
            }

            Visuals.GroundShadow(root, new Vector3(0f, 0.012f, 0f), 2.4f,
                kind == "truck" ? 7.2f : 4.8f, 0.8f);
            group.SetActive(false);
            return vehicle;
        }

        private static void AddWheels(Transform root, float z, float radius)
        {
            for (int x = -1; x <= 1; x += 2)
            {
                for (int s = -1; s <= 1; s += 2)
                {
                    GameObject pivot = new GameObject("Wheel");
                    pivot.transform.SetParent(root, false);
                    pivot.transform.localPosition = new Vector3(x * 0.9f, radius, s * z);
                    KittCar.BuildWheel(pivot.transform, radius, 0.26f, false);
                }
            }
        }

        public static EnemyVehicle BuildEnemy()
        {
            EnemyVehicle enemy = new EnemyVehicle();
            GameObject group = new GameObject("Interceptor");
            enemy.Go = group;
            Transform root = group.transform;
            Material bodyMat = GameMaterials.Paint(new Color(0.055f, 0.06f, 0.085f));
            Material cabinMat = GameMaterials.Glass;
            Material trim = GameMaterials.Trim;

            MeshUtils.MakeMeshObject("Body", MeshUtils.Wedge(2.08f, 0.66f, 4.8f, 0.26f),
                bodyMat, root).transform.localPosition = new Vector3(0f, 0.62f, 0f);
            MeshUtils.MakeMeshObject("Cabin", MeshUtils.Cabin(1.78f, 0.58f, 2.1f),
                cabinMat, root).transform.localPosition = new Vector3(0f, 1.12f, 0.22f);
            MeshUtils.Box(root, "BullBar", new Vector3(0f, 0.42f, -2.42f),
                new Vector3(2.0f, 0.22f, 0.24f), trim);

            for (int x = -1; x <= 1; x += 2)
            {
                for (int z = -1; z <= 1; z += 2)
                {
                    GameObject pivot = new GameObject("Wheel");
                    pivot.transform.SetParent(root, false);
                    pivot.transform.localPosition = new Vector3(x * 0.98f, 0.40f, z * 1.55f);
                    KittCar.BuildWheel(pivot.transform, 0.40f, 0.30f, false);
                }
            }

            MeshUtils.Box(root, "LightBarBase", new Vector3(0f, 1.46f, 0.1f),
                new Vector3(1.15f, 0.09f, 0.3f), trim);
            enemy.RedLight = MeshUtils.Box(root, "RedLight", new Vector3(-0.28f, 1.53f, 0.1f),
                new Vector3(0.42f, 0.12f, 0.18f), GameMaterials.RedLight);
            enemy.BlueLight = MeshUtils.Box(root, "BlueLight", new Vector3(0.28f, 1.53f, 0.1f),
                new Vector3(0.42f, 0.12f, 0.18f), GameMaterials.Emissive(new Color(0.1f, 0.35f, 1f), 2.4f));
            enemy.Glow = Visuals.GlowSprite(root, "LightGlow", new Vector3(0f, 1.52f, 0.12f),
                Palette.Red, 1.4f, 0.5f);

            for (int side = -1; side <= 1; side += 2)
            {
                MeshUtils.Box(root, "Tail", new Vector3(side * 0.62f, 0.72f, 2.42f),
                    new Vector3(0.50f, 0.10f, 0.02f), GameMaterials.Tail);
            }
            Visuals.GroundShadow(root, new Vector3(0f, 0.012f, 0f), 2.6f, 5.6f, 0.85f);
            group.SetActive(false);
            return enemy;
        }

        public static DataCore BuildCore()
        {
            DataCore core = new DataCore();
            GameObject group = new GameObject("DataCore");
            core.Go = group;
            core.Core = MeshUtils.MakeMeshObject("Core", MeshUtils.Octahedron(0.42f),
                GameMaterials.Emissive(new Color(1f, 0.72f, 0.26f), 2.8f), group.transform).transform;
            GameObject ring1 = MeshUtils.MakeMeshObject("Ring1", MeshUtils.Ring(0.66f, 0.75f, 40),
                GameMaterials.Emissive(new Color(1f, 0.8f, 0.4f), 2.2f), group.transform);
            ring1.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            GameObject ring2 = MeshUtils.MakeMeshObject("Ring2", MeshUtils.Ring(0.84f, 0.91f, 40),
                GameMaterials.Emissive(new Color(1f, 0.8f, 0.4f), 2.2f), group.transform);
            ring2.transform.localRotation = Quaternion.Euler(72f, 12f, 0f);
            core.Ring1 = ring1.transform;
            core.Ring2 = ring2.transform;
            Visuals.GlowSprite(group.transform, "CoreGlow", Vector3.zero,
                new Color(1f, 0.66f, 0.2f), 2.8f, 0.55f);
            group.SetActive(false);
            return core;
        }

        public static Ramp BuildRamp()
        {
            Ramp ramp = new Ramp();
            GameObject group = new GameObject("Ramp");
            ramp.Go = group;
            Transform root = group.transform;
            MeshUtils.MakeMeshObject("RampMesh", MeshUtils.Ramp(3.4f, 7.5f, 1.45f),
                GameMaterials.Paint(new Color(0.09f, 0.10f, 0.14f)), root);
            Material amber = GameMaterials.Amber;
            for (int i = 0; i < 4; i++)
            {
                float t = (i + 0.5f) / 4f;
                float z = 3.75f - t * 7.5f;
                float y = t * 1.45f + 0.035f;
                MeshUtils.Box(root, "Chevron", new Vector3(0f, y, z),
                    new Vector3(2.3f, 0.035f, 0.18f), amber,
                    Quaternion.Euler(-11f, 0f, 0f));
            }
            for (int side = -1; side <= 1; side += 2)
            {
                MeshUtils.Box(root, "Edge", new Vector3(side * 1.7f, 0.72f, 0f),
                    new Vector3(0.09f, 0.06f, 7.5f), GameMaterials.Cyan,
                    Quaternion.Euler(-11f, 0f, 0f));
            }
            group.SetActive(false);
            return ramp;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace KnightRider3D
{
    /// <summary>
    /// The neon Nevada highway. The road texture and roadside furniture scroll
    /// toward the player while the distant skyline and mountains stay put.
    /// </summary>
    public class WorldBuilder : MonoBehaviour
    {
        public const float RoadHalf = 9.2f;
        public static readonly float[] Lanes = { -6.7f, -2.23f, 2.23f, 6.7f };
        public const float ScrollSpan = 520f;

        public Material RoadMaterial { get; private set; }
        private readonly List<Transform> _scrollables = new List<Transform>();
        private Transform _world;

        public void Build()
        {
            _world = transform;

            BuildSky();
            BuildGroundAndRoad();
            BuildGuardRails();
            BuildStreetFurniture();
            BuildBackdrop();
            BuildTitleBackdrop();
        }

        private void BuildSky()
        {
            GameObject sky = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            sky.name = "SkyDome";
            Collider col = sky.GetComponent<Collider>();
            if (col != null) Destroy(col);
            sky.transform.SetParent(_world, false);
            sky.transform.localScale = Vector3.one * 900f;
            Material mat = new Material(Shader.Find("Sprites/Default"));
            mat.mainTexture = TextureFactory.Sky;
            mat.color = Color.white;
            MeshRenderer r = sky.GetComponent<MeshRenderer>();
            r.sharedMaterial = mat;
            r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            r.receiveShadows = false;
            r.sortingOrder = -100;

            Visuals.MoonSprite(_world, new Vector3(-190f, 245f, -820f), 120f);
            Visuals.MoonSprite(_world, new Vector3(78f, 105f, 240f), 52f);
        }

        private void BuildGroundAndRoad()
        {
            // Desert floor
            Material groundMat = GameMaterials.Paint(new Color(0.035f, 0.031f, 0.052f));
            GameObject ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
            ground.name = "Desert";
            Collider gc = ground.GetComponent<Collider>();
            if (gc != null) Destroy(gc);
            ground.transform.SetParent(_world, false);
            ground.transform.localPosition = new Vector3(0f, -0.06f, -180f);
            ground.transform.localScale = new Vector3(40f, 1f, 70f);
            MeshRenderer gr = ground.GetComponent<MeshRenderer>();
            gr.sharedMaterial = groundMat;
            gr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            gr.receiveShadows = false;

            RoadMaterial = GameMaterials.Paint(new Color(0.12f, 0.13f, 0.17f));
            RoadMaterial.mainTexture = TextureFactory.Asphalt;
            RoadMaterial.mainTextureScale = new Vector2(1f, 15.625f);
            if (RoadMaterial.HasProperty("_Glossiness")) RoadMaterial.SetFloat("_Glossiness", 0.55f);

            GameObject road = GameObject.CreatePrimitive(PrimitiveType.Plane);
            road.name = "Highway";
            Collider rc = road.GetComponent<Collider>();
            if (rc != null) Destroy(rc);
            road.transform.SetParent(_world, false);
            road.transform.localPosition = new Vector3(0f, 0f, -200f);
            road.transform.localScale = new Vector3(1.84f, 1f, 50f);
            MeshRenderer rr = road.GetComponent<MeshRenderer>();
            rr.sharedMaterial = RoadMaterial;
            rr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            rr.receiveShadows = false;

            // Concrete shoulders
            Material shoulderMat = GameMaterials.Paint(new Color(0.16f, 0.145f, 0.15f));
            for (int side = -1; side <= 1; side += 2)
            {
                GameObject shoulder = GameObject.CreatePrimitive(PrimitiveType.Plane);
                shoulder.name = "Shoulder";
                Collider sc = shoulder.GetComponent<Collider>();
                if (sc != null) Destroy(sc);
                shoulder.transform.SetParent(_world, false);
                shoulder.transform.localPosition = new Vector3(side * 13.2f, 0.005f, -200f);
                shoulder.transform.localScale = new Vector3(0.8f, 1f, 50f);
                MeshRenderer sr = shoulder.GetComponent<MeshRenderer>();
                sr.sharedMaterial = shoulderMat;
                sr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                sr.receiveShadows = false;
            }
        }

        private void BuildGuardRails()
        {
            Material railMat = GameMaterials.Paint(new Color(0.21f, 0.22f, 0.26f));
            for (int side = -1; side <= 1; side += 2)
            {
                MeshUtils.Box(_world, "GuardRail", new Vector3(side * 9.65f, 0.7f, -200f),
                    new Vector3(0.09f, 0.16f, 500f), railMat);
                MeshUtils.Box(_world, "GuardRailLow", new Vector3(side * 9.65f, 0.44f, -200f),
                    new Vector3(0.07f, 0.10f, 500f), railMat);
                for (int z = 45; z >= -445; z -= 14)
                {
                    MeshUtils.Box(_world, "RailPost", new Vector3(side * 9.65f, 0.48f, z),
                        new Vector3(0.09f, 1.0f, 0.12f), railMat);
                }
            }

            // Reflective posts scroll so the speed reads even at the edges.
            Material reflectorMat = GameMaterials.Amber;
            Material postMat = GameMaterials.Trim;
            for (int side = -1; side <= 1; side += 2)
            {
                for (int i = 0; i < 26; i++)
                {
                    GameObject root = new GameObject("Reflector");
                    root.transform.SetParent(_world, false);
                    root.transform.localPosition = new Vector3(side * 9.3f, 0f, 30f - i * 20f);
                    MeshUtils.Box(root.transform, "Post", new Vector3(0f, 0.45f, 0f),
                        new Vector3(0.05f, 0.9f, 0.05f), postMat);
                    MeshUtils.Box(root.transform, "Reflector", new Vector3(0f, 0.82f, 0f),
                        new Vector3(0.10f, 0.12f, 0.03f), reflectorMat);
                    _scrollables.Add(root.transform);
                }
            }
        }

        private void BuildStreetFurniture()
        {
            Material poleMat = GameMaterials.Paint(new Color(0.16f, 0.17f, 0.2f));
            Material lampMat = GameMaterials.Emissive(new Color(1f, 0.66f, 0.28f), 3.2f);
            for (int i = 0; i < 12; i++)
            {
                int side = i % 2 == 0 ? -1 : 1;
                GameObject root = new GameObject("Streetlight");
                root.transform.SetParent(_world, false);
                root.transform.localPosition = new Vector3(side * 11.4f, 0f, 20f - i * 42f);
                MeshUtils.Cylinder(root.transform, "Pole", new Vector3(0f, 4.2f, 0f),
                    new Vector3(0.16f, 4.3f, 0.16f), poleMat);
                MeshUtils.Box(root.transform, "Arm", new Vector3(side * -1.3f, 8.35f, 0f),
                    new Vector3(2.6f, 0.09f, 0.12f), poleMat);
                MeshUtils.Box(root.transform, "Lamp", new Vector3(side * -2.45f, 8.25f, 0f),
                    new Vector3(0.55f, 0.10f, 0.22f), lampMat);
                Visuals.GlowSprite(root.transform, "LampGlow", new Vector3(side * -2.45f, 8.15f, 0f),
                    new Color(1f, 0.65f, 0.28f), 1.5f, 0.7f);
                _scrollables.Add(root.transform);
            }

            // Gantry signs
            BuildGantry("LAS VEGAS", "61 · KNIGHT FOUNDATION TEST RANGE", -85f);
            BuildGantry("SECTOR 7", "K.I.T.T. PURSUIT CORRIDOR", -235f);
            BuildGantry("NEVADA", "SPEED LIMIT 300 · TURBO ONLY", -390f);

            // Overpasses
            for (int i = 0; i < 2; i++)
            {
                GameObject root = new GameObject("Overpass");
                root.transform.SetParent(_world, false);
                root.transform.localPosition = new Vector3(0f, 0f, -155f - i * 230f);
                Material concrete = GameMaterials.Paint(new Color(0.12f, 0.115f, 0.13f));
                MeshUtils.Box(root.transform, "Deck", new Vector3(0f, 7.0f, 0f),
                    new Vector3(27f, 0.85f, 3.2f), concrete);
                MeshUtils.Box(root.transform, "UnderGlow", new Vector3(0f, 6.52f, 0f),
                    new Vector3(25f, 0.05f, 0.35f), GameMaterials.Cyan);
                for (int side = -1; side <= 1; side += 2)
                {
                    MeshUtils.Box(root.transform, "Column", new Vector3(side * 11.5f, 3.2f, 0f),
                        new Vector3(1.0f, 6.4f, 1.2f), concrete);
                }
                _scrollables.Add(root.transform);
            }

            // Cacti and rocks
            Material cactusMat = GameMaterials.Paint(new Color(0.10f, 0.20f, 0.13f));
            Material rockMat = GameMaterials.Paint(new Color(0.12f, 0.11f, 0.15f));
            for (int i = 0; i < 22; i++)
            {
                int side = Random.value < 0.5f ? -1 : 1;
                float x = side * Random.Range(13f, 30f);
                float z = Random.Range(-450f, 15f);
                if (i % 3 == 0)
                {
                    GameObject rock = MeshUtils.Box(_world, "Rock", new Vector3(x, 0.4f, z),
                        new Vector3(Random.Range(1.4f, 4.2f), Random.Range(0.8f, 2.6f), Random.Range(1.4f, 3.6f)),
                        rockMat, Quaternion.Euler(Random.Range(-12f, 12f), Random.Range(0f, 360f), Random.Range(-8f, 8f)));
                    _scrollables.Add(rock.transform);
                }
                else
                {
                    GameObject root = new GameObject("Cactus");
                    root.transform.SetParent(_world, false);
                    root.transform.localPosition = new Vector3(x, 0f, z);
                    MeshUtils.Cylinder(root.transform, "Trunk", new Vector3(0f, 1.4f, 0f),
                        new Vector3(0.32f, 1.4f, 0.32f), cactusMat);
                    MeshUtils.Box(root.transform, "Arm", new Vector3(0.38f, 1.7f, 0f),
                        new Vector3(0.16f, 0.8f, 0.16f), cactusMat);
                    MeshUtils.Box(root.transform, "ArmTop", new Vector3(0.62f, 2.05f, 0f),
                        new Vector3(0.5f, 0.16f, 0.16f), cactusMat);
                    _scrollables.Add(root.transform);
                }
            }
        }

        private void BuildGantry(string title, string subtitle, float z)
        {
            GameObject root = new GameObject("Sign_" + title);
            root.transform.SetParent(_world, false);
            root.transform.localPosition = new Vector3(0f, 0f, z);
            Material poleMat = GameMaterials.Paint(new Color(0.11f, 0.12f, 0.15f));
            Material panelMat = GameMaterials.Paint(new Color(0.025f, 0.03f, 0.045f));
            for (int side = -1; side <= 1; side += 2)
            {
                MeshUtils.Box(root.transform, "Post", new Vector3(side * 10.7f, 3.9f, 0f),
                    new Vector3(0.20f, 7.8f, 0.20f), poleMat);
            }
            MeshUtils.Box(root.transform, "Beam", new Vector3(0f, 7.65f, 0f),
                new Vector3(21.4f, 0.16f, 0.18f), poleMat);
            MeshUtils.Box(root.transform, "Panel", new Vector3(0f, 6.1f, 0f),
                new Vector3(8.4f, 2.9f, 0.16f), panelMat);
            MeshUtils.Box(root.transform, "PanelLine", new Vector3(0f, 7.42f, 0.10f),
                new Vector3(8.0f, 0.035f, 0.02f), GameMaterials.Amber);
            MeshUtils.Box(root.transform, "PanelLine2", new Vector3(0f, 4.72f, 0.10f),
                new Vector3(8.0f, 0.02f, 0.02f), GameMaterials.Amber);
            Visuals.GlowSprite(root.transform, "SignGlow", new Vector3(0f, 6.1f, 0.6f),
                new Color(1f, 0.75f, 0.32f), 4.5f, 0.14f);

            AddText(root.transform, title, new Vector3(0f, 6.45f, 0.12f), 0.085f, 64,
                new Color(1f, 0.95f, 0.85f));
            AddText(root.transform, subtitle, new Vector3(0f, 5.55f, 0.12f), 0.042f, 44,
                new Color(0.72f, 0.78f, 0.88f));

            _scrollables.Add(root.transform);
        }

        private void AddText(Transform parent, string text, Vector3 pos, float characterSize,
            int fontSize, Color color)
        {
            GameObject go = new GameObject("Text");
            go.transform.SetParent(parent, false);
            go.transform.localPosition = pos;
            TextMesh tm = go.AddComponent<TextMesh>();
            tm.text = text;
            tm.font = GameFonts.Display;
            tm.fontSize = fontSize;
            tm.characterSize = characterSize;
            tm.anchor = TextAnchor.MiddleCenter;
            tm.alignment = TextAlignment.Center;
            tm.color = color;
            MeshRenderer mr = go.GetComponent<MeshRenderer>();
            if (mr != null && GameFonts.Display != null) mr.sharedMaterial = GameFonts.Display.material;
        }

        private void BuildBackdrop()
        {
            // City silhouette, mountains and distant haze behind the highway.
            GameObject city = MeshUtils.MakeMeshObject("City", MeshUtils.Quad(760f, 110f),
                GameMaterials.Unlit(new Color(0.62f, 0.55f, 0.76f), TextureFactory.City), _world);
            city.transform.localPosition = new Vector3(0f, 33f, -585f);
            city.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);

            Material mtnFar = GameMaterials.Unlit(new Color(0.075f, 0.055f, 0.11f));
            Material mtnMid = GameMaterials.Unlit(new Color(0.055f, 0.038f, 0.082f));
            GameObject m1 = MeshUtils.MakeMeshObject("MountainsFar",
                MeshUtils.MountainRange(1100f, 210f, 30, 12), mtnFar, _world);
            m1.transform.localPosition = new Vector3(0f, -6f, -760f);
            GameObject m2 = MeshUtils.MakeMeshObject("MountainsNear",
                MeshUtils.MountainRange(950f, 135f, 26, 71), mtnMid, _world);
            m2.transform.localPosition = new Vector3(0f, -6f, -610f);
        }

        private void BuildTitleBackdrop()
        {
            // The attract camera looks back up the highway (+Z), so this is the
            // postcard behind K.I.T.T. on the title screen.
            Material mtnA = GameMaterials.Unlit(new Color(0.085f, 0.06f, 0.12f));
            Material mtnB = GameMaterials.Unlit(new Color(0.055f, 0.04f, 0.085f));
            GameObject m1 = MeshUtils.MakeMeshObject("TitleMountains",
                MeshUtils.MountainRange(620f, 140f, 24, 44), mtnA, _world);
            m1.transform.localPosition = new Vector3(30f, -8f, 290f);
            GameObject m2 = MeshUtils.MakeMeshObject("TitleMountainsNear",
                MeshUtils.MountainRange(520f, 95f, 20, 9), mtnB, _world);
            m2.transform.localPosition = new Vector3(15f, -6f, 240f);

            GameObject city = MeshUtils.MakeMeshObject("TitleCity", MeshUtils.Quad(420f, 80f),
                GameMaterials.Unlit(new Color(0.7f, 0.55f, 0.72f), TextureFactory.City), _world);
            city.transform.localPosition = new Vector3(10f, 24f, 270f);

            // Neon arch spanning the highway behind K.I.T.T.
            Material pole = GameMaterials.Paint(new Color(0.05f, 0.055f, 0.08f));
            Material cyan = GameMaterials.Cyan;
            Material red = GameMaterials.RedLight;
            GameObject arch = new GameObject("NeonArch");
            arch.transform.SetParent(_world, false);
            arch.transform.localPosition = new Vector3(0f, 0f, 32f);
            for (int side = -1; side <= 1; side += 2)
            {
                MeshUtils.Box(arch.transform, "ArchPost", new Vector3(side * 10.2f, 3.2f, 0f),
                    new Vector3(0.45f, 6.4f, 0.45f), pole);
                MeshUtils.Box(arch.transform, "ArchNeon", new Vector3(side * 9.92f, 3.2f, 0f),
                    new Vector3(0.06f, 6.2f, 0.06f), cyan);
            }
            MeshUtils.Box(arch.transform, "ArchTop", new Vector3(0f, 7.0f, 0f),
                new Vector3(21f, 0.45f, 0.45f), pole);
            MeshUtils.Box(arch.transform, "ArchTopNeon", new Vector3(0f, 6.74f, 0f),
                new Vector3(20.6f, 0.06f, 0.06f), red);
            AddText(arch.transform, "KNIGHT FOUNDATION", new Vector3(0f, 7.0f, -0.28f), 0.055f, 48,
                new Color(1f, 0.7f, 0.72f));
            Visuals.GlowSprite(arch.transform, "ArchGlow", new Vector3(0f, 6.7f, -0.4f),
                Palette.Red, 7.5f, 0.12f);

            // Warm horizon glows behind the sign.
            Visuals.GlowSprite(_world, "HorizonGlowA", new Vector3(-90f, 30f, 260f),
                new Color(1f, 0.35f, 0.25f), 80f, 0.16f);
            Visuals.GlowSprite(_world, "HorizonGlowB", new Vector3(100f, 25f, 250f),
                new Color(0.35f, 0.55f, 1f), 60f, 0.12f);
        }

        public void ScrollWorld(float dt, float speed)
        {
            float dz = speed * dt;
            if (RoadMaterial != null)
            {
                Vector2 offset = RoadMaterial.mainTextureOffset;
                offset.y -= dz / 32f;
                RoadMaterial.mainTextureOffset = offset;
            }
            for (int i = 0; i < _scrollables.Count; i++)
            {
                Transform t = _scrollables[i];
                Vector3 p = t.localPosition;
                p.z += dz;
                if (p.z > 70f) p.z -= ScrollSpan;
                t.localPosition = p;
            }
        }
    }
}

using UnityEngine;

namespace KnightRider3D
{
    public class ChaseCamera : MonoBehaviour
    {
        private Camera _camera;

        public void Init(Camera cam)
        {
            _camera = cam;
            _camera.fieldOfView = 52f;
            _camera.nearClipPlane = 0.1f;
            _camera.farClipPlane = 2200f;
            _camera.clearFlags = CameraClearFlags.SolidColor;
            _camera.backgroundColor = new Color(0.018f, 0.012f, 0.035f);
            _camera.allowHDR = true;
        }

        public void Tick(float dt, bool menu, float carX, float speed, float jumpY,
            bool boost, float time, float shake)
        {
            if (menu)
            {
                float a = 0.78f + Mathf.Sin(time * 0.1f) * 0.1f;
                Vector3 desired = new Vector3(
                    carX - 8.4f * Mathf.Cos(a),
                    2.3f + Mathf.Sin(time * 0.27f) * 0.1f,
                    -1.8f - 9.2f * Mathf.Sin(a));
                transform.position = Vector3.Lerp(transform.position, desired, 1f - Mathf.Exp(-4f * dt));
                transform.LookAt(new Vector3(carX + 1.9f, 0.74f, 0.35f));
                _camera.fieldOfView = Mathf.Lerp(_camera.fieldOfView, 40f, 1f - Mathf.Exp(-4f * dt));
                ApplyShake(shake);
                return;
            }

            float speedNorm = Mathf.Clamp01(speed / 134f);
            Vector3 target = new Vector3(
                carX * 0.8f,
                3.55f + jumpY * 0.55f + speedNorm * 0.55f,
                8.4f + speedNorm * 2.4f);
            transform.position = Vector3.Lerp(transform.position, target, 1f - Mathf.Exp(-5.2f * dt));
            transform.LookAt(new Vector3(carX * 0.62f, 1f + jumpY * 0.8f, -7f - speedNorm * 5f));
            float targetFov = 61f + speedNorm * 11f + (boost ? 5f : 0f);
            _camera.fieldOfView = Mathf.Lerp(_camera.fieldOfView, targetFov, 1f - Mathf.Exp(-3.6f * dt));
            ApplyShake(shake);
        }

        private void ApplyShake(float shake)
        {
            if (shake <= 0.001f) return;
            transform.position += new Vector3(
                (Random.value - 0.5f) * 0.42f * shake,
                (Random.value - 0.5f) * 0.30f * shake,
                0f);
            transform.Rotate(0f, 0f, (Random.value - 0.5f) * 1.2f * shake, Space.Self);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace KnightRider3D
{
    /// <summary>
    /// Original synth score and SFX generated from raw samples at runtime.
    /// No copyrighted Knight Rider material is used.
    /// </summary>
    public class SynthAudio : MonoBehaviour
    {
        private const int Rate = 44100;
        private AudioSource _engine;
        private AudioSource _music;
        private AudioSource _sfx;
        private readonly Dictionary<string, AudioClip> _clips = new Dictionary<string, AudioClip>();
        private string _mode = "menu";
        private bool _muted;

        public bool Muted => _muted;

        public void Init()
        {
            _engine = MakeSource("Engine", true);
            _music = MakeSource("Music", true);
            _sfx = MakeSource("Sfx", false);
            _sfx.ignoreListenerPause = true;

            _engine.clip = BuildEngine();
            _engine.volume = 0f;
            _engine.Play();

            _music.clip = BuildMusic();
            _music.volume = 0.12f;
            _music.Play();

            _clips["laser"] = BuildLaser();
            _clips["crash"] = BuildCrash();
            _clips["pickup"] = BuildPickup();
            _clips["boost"] = BuildBoost();
            _clips["jump"] = BuildJump();
            _clips["near"] = BuildNear();
            _clips["over"] = BuildGameOver();
            _clips["click"] = BuildClick();
        }

        private AudioSource MakeSource(string name, bool loop)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(transform, false);
            AudioSource src = go.AddComponent<AudioSource>();
            src.playOnAwake = false;
            src.loop = loop;
            src.spatialBlend = 0f;
            return src;
        }

        public void SetMode(string mode)
        {
            _mode = mode;
            if (_music == null) return;
            float target = 0.12f;
            if (mode == "playing") target = 0.17f;
            else if (mode == "paused") target = 0.045f;
            else if (mode == "over") target = 0.08f;
            _music.volume = _muted ? 0f : target;
        }

        public void ToggleMute()
        {
            _muted = !_muted;
            _music.volume = _muted ? 0f : _mode == "playing" ? 0.17f : 0.12f;
            if (_muted) _engine.volume = 0f;
        }

        public void UpdateAudio(float dt, float speedNorm, bool boost, bool playing)
        {
            if (_engine == null) return;
            float engineTarget = playing ? (_muted ? 0f : 0.085f + speedNorm * 0.06f) : 0f;
            _engine.volume = Mathf.Lerp(_engine.volume, engineTarget, 1f - Mathf.Exp(-5f * dt));
            _engine.pitch = 0.58f + speedNorm * 0.95f + (boost ? 0.16f : 0f);
        }

        public void Laser() { Play("laser", 0.55f); }
        public void Crash() { Play("crash", 0.8f); }
        public void Pickup() { Play("pickup", 0.5f); }
        public void Boost() { Play("boost", 0.65f); }
        public void Jump() { Play("jump", 0.6f); }
        public void NearMiss() { Play("near", 0.4f); }
        public void GameOver() { Play("over", 0.7f); }
        public void Click() { Play("click", 0.4f); }

        private void Play(string key, float volume)
        {
            if (_muted || _sfx == null) return;
            AudioClip clip;
            if (_clips.TryGetValue(key, out clip)) _sfx.PlayOneShot(clip, volume);
        }

        private static AudioClip Clip(string name, float[] data)
        {
            AudioClip clip = AudioClip.Create(name, data.Length, 1, Rate, false);
            clip.SetData(data, 0);
            return clip;
        }

        private static void Normalize(float[] data, float peak)
        {
            float max = 0.0001f;
            for (int i = 0; i < data.Length; i++) max = Mathf.Max(max, Mathf.Abs(data[i]));
            float scale = peak / max;
            for (int i = 0; i < data.Length; i++) data[i] *= scale;
        }

        private static uint _noiseSeed = 0x9e3779b9u;
        private static float Noise()
        {
            _noiseSeed ^= _noiseSeed << 13;
            _noiseSeed ^= _noiseSeed >> 17;
            _noiseSeed ^= _noiseSeed << 5;
            return (_noiseSeed / (float)uint.MaxValue) * 2f - 1f;
        }

        private static AudioClip BuildEngine()
        {
            int n = Rate * 2;
            float[] data = new float[n];
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                float rumble = Mathf.Sin(2f * Mathf.PI * 55f * t) * 0.34f;
                rumble += Mathf.Sin(2f * Mathf.PI * 110f * t) * 0.18f;
                rumble += Mathf.Sin(2f * Mathf.PI * 165f * t) * 0.09f;
                rumble += Mathf.Sin(2f * Mathf.PI * 27.5f * t) * 0.12f;
                float pulse = 0.72f + 0.28f * Mathf.Sin(2f * Mathf.PI * 2f * t);
                data[i] = rumble * pulse + Noise() * 0.025f;
            }
            Normalize(data, 0.7f);
            // Smooth the loop seam
            int fade = Rate / 50;
            for (int i = 0; i < fade; i++)
            {
                float k = (float)i / fade;
                data[i] *= k;
                data[n - 1 - i] *= k;
            }
            return Clip("EngineLoop", data);
        }

        private static readonly float[] BassNotes = { 55f, 43.65f, 65.41f, 49f };
        private static readonly float[] ArpNotes = { 440f, 523.25f, 659.25f, 783.99f, 659.25f, 523.25f, 493.88f, 392f };

        private static AudioClip BuildMusic()
        {
            int n = Rate * 8;
            float[] data = new float[n];
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                int beat = (int)(t / 0.5f);
                int bar = (beat / 4) % 4;
                float beatPhase = t % 0.5f;
                float barPhase = t % 2f;

                // Bass sequencer
                float bassFreq = BassNotes[bar];
                float bassEnv = Mathf.Exp(-beatPhase * 3.2f);
                float bass = Mathf.Sin(2f * Mathf.PI * bassFreq * t) * 0.22f * bassEnv;
                bass += Mathf.Sin(2f * Mathf.PI * bassFreq * 2f * t) * 0.06f * bassEnv;

                // Sixteenth arpeggio
                int step = (int)(t / 0.25f);
                float arpFreq = ArpNotes[step % ArpNotes.Length];
                float arpPhase = t % 0.25f;
                float arpEnv = Mathf.Exp(-arpPhase * 11f);
                float arp = Mathf.Sin(2f * Mathf.PI * arpFreq * t) * 0.055f * arpEnv;
                arp += Mathf.Sin(2f * Mathf.PI * arpFreq * 2.01f * t) * 0.018f * arpEnv;

                // Pad
                float pad = Mathf.Sin(2f * Mathf.PI * (bassFreq * 4f) * t) * 0.022f;
                pad += Mathf.Sin(2f * Mathf.PI * (bassFreq * 5f) * t) * 0.018f;
                pad += Mathf.Sin(2f * Mathf.PI * (bassFreq * 6f) * t) * 0.012f;
                pad *= 0.65f + 0.35f * Mathf.Sin(2f * Mathf.PI * 0.25f * t);

                // Kick
                float kickEnv = Mathf.Exp(-beatPhase * 15f);
                float kickFreq = 42f + 90f * Mathf.Exp(-beatPhase * 26f);
                float kick = Mathf.Sin(2f * Mathf.PI * kickFreq * beatPhase) * 0.38f * kickEnv;

                // Snare on beats 2 and 4
                int beatInBar = beat % 4;
                float snare = 0f;
                if (beatInBar == 1 || beatInBar == 3)
                {
                    snare = Noise() * 0.12f * Mathf.Exp(-beatPhase * 18f);
                    snare += Mathf.Sin(2f * Mathf.PI * 180f * t) * 0.05f * Mathf.Exp(-beatPhase * 22f);
                }

                // Hats on eighths
                float hatPhase = t % 0.25f;
                float hat = Noise() * 0.028f * Mathf.Exp(-hatPhase * 55f);

                // Slow filter-ish tremolo on the pad for movement
                float side = Mathf.Sin(2f * Mathf.PI * 0.125f * t) * 0.02f;

                data[i] = bass + arp + pad + kick + snare + hat + side;
            }
            Normalize(data, 0.82f);
            int seam = Rate / 40;
            for (int i = 0; i < seam; i++)
            {
                float k = (float)i / seam;
                data[i] *= k;
                data[n - 1 - i] *= k;
            }
            return Clip("NeonPursuitLoop", data);
        }

        private static AudioClip BuildLaser()
        {
            int n = (int)(Rate * 0.34f);
            float[] data = new float[n];
            float phase = 0f;
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                float f = Mathf.Lerp(1900f, 240f, Mathf.Clamp01(t / 0.30f));
                phase += 2f * Mathf.PI * f / Rate;
                float env = Mathf.Exp(-t * 9f);
                float sq = Mathf.Sign(Mathf.Sin(phase)) * 0.22f;
                data[i] = (sq + Mathf.Sin(phase) * 0.18f) * env + Noise() * 0.05f * env;
            }
            Normalize(data, 0.75f);
            return Clip("Laser", data);
        }

        private static AudioClip BuildCrash()
        {
            int n = (int)(Rate * 0.6f);
            float[] data = new float[n];
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                float env = Mathf.Exp(-t * 7f);
                float body = Mathf.Sin(2f * Mathf.PI * (70f - 30f * t) * t) * 0.5f;
                data[i] = (Noise() * 0.6f + body) * env;
            }
            Normalize(data, 0.9f);
            return Clip("Crash", data);
        }

        private static AudioClip BuildPickup()
        {
            int n = (int)(Rate * 0.55f);
            float[] data = new float[n];
            float[] notes = { 659.25f, 880f, 1318.5f };
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                int step = Mathf.Min(2, (int)(t / 0.15f));
                float local = t - step * 0.15f;
                float env = Mathf.Exp(-local * 9f);
                data[i] = Mathf.Sin(2f * Mathf.PI * notes[step] * t) * 0.35f * env;
                data[i] += Mathf.Sin(2f * Mathf.PI * notes[step] * 2f * t) * 0.08f * env;
            }
            Normalize(data, 0.7f);
            return Clip("Pickup", data);
        }

        private static AudioClip BuildBoost()
        {
            int n = (int)(Rate * 0.8f);
            float[] data = new float[n];
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                float f = Mathf.Lerp(90f, 420f, t / 0.8f);
                float env = Mathf.Exp(-t * 3.4f);
                data[i] = (Mathf.Sin(2f * Mathf.PI * f * t) * 0.25f + Noise() * 0.3f) * env;
            }
            Normalize(data, 0.8f);
            return Clip("Boost", data);
        }

        private static AudioClip BuildJump()
        {
            int n = (int)(Rate * 0.45f);
            float[] data = new float[n];
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                float f = Mathf.Lerp(180f, 760f, Mathf.Clamp01(t / 0.4f));
                float env = Mathf.Sin(Mathf.Clamp01(t / 0.45f) * Mathf.PI);
                data[i] = Mathf.Sin(2f * Mathf.PI * f * t) * 0.35f * env;
            }
            Normalize(data, 0.7f);
            return Clip("Jump", data);
        }

        private static AudioClip BuildNear()
        {
            int n = (int)(Rate * 0.18f);
            float[] data = new float[n];
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                float env = Mathf.Exp(-t * 22f);
                data[i] = Mathf.Sin(2f * Mathf.PI * 1450f * t) * 0.3f * env;
            }
            Normalize(data, 0.65f);
            return Clip("NearMiss", data);
        }

        private static AudioClip BuildGameOver()
        {
            int n = (int)(Rate * 1.5f);
            float[] data = new float[n];
            float[] notes = { 220f, 185f, 146.83f, 110f };
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                int step = Mathf.Min(3, (int)(t / 0.34f));
                float local = t - step * 0.34f;
                float env = Mathf.Exp(-local * 3.2f);
                data[i] = Mathf.Sin(2f * Mathf.PI * notes[step] * t) * 0.28f * env;
                data[i] += Mathf.Sin(2f * Mathf.PI * notes[step] * 0.5f * t) * 0.2f * env;
            }
            Normalize(data, 0.75f);
            return Clip("GameOver", data);
        }

        private static AudioClip BuildClick()
        {
            int n = (int)(Rate * 0.07f);
            float[] data = new float[n];
            for (int i = 0; i < n; i++)
            {
                float t = (float)i / Rate;
                float env = Mathf.Exp(-t * 70f);
                data[i] = Mathf.Sin(2f * Mathf.PI * 900f * t) * 0.35f * env;
            }
            Normalize(data, 0.6f);
            return Clip("Click", data);
        }
    }
}

