            Shield = 100f;
            Score = 0f;
            Distance = 0f;
            TimeLeft = StartTime;
            Combo = 0;
            ComboTimer = 0f;
            Kills = 0;
            Cores = 0;
            TopSpeed = 0f;
            JumpY = 0f;
            JumpV = 0f;
            Airborne = false;
            BoostActive = false;
