@keyframes blink { 0%, 70% { opacity: 1; } 85% { opacity: 0.2; } 100% { opacity: 1; } }
.mission-name { font-family: var(--display); font-weight: 900; font-size: clamp(15px, 1.5vw, 19px); letter-spacing: 0.11em; color: #fff; margin: 5px 0 10px; text-shadow: 0 0 18px rgba(255, 36, 56, 0.35); }
