@keyframes comboPop { from { transform: scale(1.35); filter: brightness(2); } to { transform: scale(1); } }

.hud-right { position: absolute; top: max(18px, env(safe-area-inset-top)); right: max(22px, env(safe-area-inset-right)); margin-top: 82px; display: flex; gap: 8px; pointer-events: auto; }
.icon-btn {
