.speed-panel { display: flex; flex-direction: column; align-items: center; margin-bottom: 2px; }
.scanner-hud { display: flex; gap: 4px; padding: 5px 10px; margin-bottom: -6px; background: rgba(4, 5, 10, 0.72); border: 1px solid rgba(255, 36, 56, 0.35); border-bottom: 0; z-index: 2; clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 100%, 0 100%); }
.scanner-hud span { width: 12px; height: 7px; background: #471017; transition: background 0.05s, box-shadow 0.05s; transform: skewX(-12deg); }
.scanner-hud span.on { background: var(--red-hot); box-shadow: 0 0 12px var(--red), 0 0 4px #fff inset; }

.speed-ring {
  position: relative; width: clamp(118px, 11vw, 152px); aspect-ratio: 1; border-radius: 50%;
}
.speed-ring::before {
  content: ""; position: absolute; inset: 0; border-radius: 50%; pointer-events: none;
  background: conic-gradient(from 135deg,
    rgba(255, 36, 56, 0.98) 0deg,
    rgba(255, 90, 77, 0.95) calc(var(--p) * 270deg),
    rgba(255, 255, 255, 0.075) calc(var(--p) * 270deg) 270deg,
    transparent 270deg 360deg);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 10px), #000 calc(100% - 9px));
          mask: radial-gradient(farthest-side, transparent calc(100% - 10px), #000 calc(100% - 9px));
  filter: drop-shadow(0 0 12px rgba(255, 36, 56, 0.35));
}
