  background: repeating-conic-gradient(from 135deg, rgba(255, 255, 255, 0.45) 0 1deg, transparent 1deg 13.5deg);
  -webkit-mask: radial-gradient(farthest-side, transparent 62%, #000 63% 67%, transparent 68%);
