.speed-inner { position: absolute; inset: 12px; border-radius: 50%; background: radial-gradient(circle at 50% 42%, rgba(16, 19, 30, 0.92), rgba(3, 4, 9, 0.96)); display: flex; flex-direction: column; align-items: center; justify-content: center; border: 1px solid rgba(255, 255, 255, 0.06); }
.speed-number { font-family: var(--display); font-weight: 900; font-size: clamp(30px, 3.3vw, 46px); line-height: 0.95; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; text-shadow: 0 0 24px rgba(255, 255, 255, 0.28); }
.speed-unit { font-family: var(--display); font-size: 8px; letter-spacing: 0.42em; color: var(--red-hot); margin-top: 2px; text-indent: 0.42em; }
.gear { position: absolute; top: 22%; left: 50%; transform: translateX(-50%); font-family: var(--display); font-size: 8px; letter-spacing: 0.2em; color: var(--muted); }
.speed-caption { display: flex; flex-direction: column; align-items: center; gap: 2px; margin-top: 5px; font-family: var(--display); font-size: 7px; letter-spacing: 0.2em; color: var(--muted); }
.speed-caption span:first-child { color: var(--red-hot); font-size: 9px; letter-spacing: 0.5em; text-indent: 0.5em; }

.pursuit { padding: 11px 14px; width: 190px; border-bottom: 2px solid rgba(127, 232, 255, 0.5); }
.pursuit-row { display: flex; justify-content: space-between; font-family: var(--display); font-size: 9px; letter-spacing: 0.12em; color: #d7dfef; padding: 4px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.06); }
.pursuit-row span:first-child { color: var(--muted); }
.pursuit-row .kos { color: var(--red-hot); }
.pursuit-row .lazer { color: var(--cyan); }
.pursuit-row .heat { color: var(--amber); }
.pursuit-hint { margin-top: 7px; font-size: 10px; letter-spacing: 0.16em; color: var(--muted); font-weight: 600; }
#laserState.ready { color: var(--cyan); text-shadow: 0 0 10px rgba(127, 232, 255, 0.6); }
#laserState.cool { color: var(--amber); }
#heatState.hot { color: var(--red-hot); }

/* ============================ TITLE ============================ */
.screen { position: absolute; inset: 0; z-index: 10; }
#startScreen {
  display: flex; flex-direction: column; justify-content: center;
  padding: max(24px, env(safe-area-inset-top)) clamp(22px, 6vw, 96px) max(22px, env(safe-area-inset-bottom));
  background:
    linear-gradient(90deg, rgba(3, 4, 9, 0.92) 0%, rgba(3, 4, 9, 0.7) 34%, rgba(3, 4, 9, 0.12) 62%, rgba(3, 4, 9, 0.3) 100%),
    linear-gradient(180deg, rgba(3, 4, 9, 0.55) 0%, transparent 30%, transparent 70%, rgba(3, 4, 9, 0.8) 100%);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
#startScreen.leaving { opacity: 0; transform: scale(1.03); pointer-events: none; }
.start-glow { position: absolute; right: -5%; top: 40%; width: 55vw; height: 55vw; transform: translateY(-50%); background: radial-gradient(circle, rgba(255, 36, 56, 0.12), transparent 62%); pointer-events: none; }
.start-top { position: absolute; top: max(22px, env(safe-area-inset-top)); left: clamp(22px, 6vw, 96px); right: clamp(22px, 6vw, 96px); display: flex; justify-content: space-between; align-items: center; font-family: var(--display); font-size: 8px; letter-spacing: 0.28em; color: #8d96aa; }
.kf-mark { display: flex; align-items: center; gap: 9px; color: #cfd6e4; }
.kf-bars { display: flex; gap: 2px; }
.kf-bars i { width: 3px; height: 11px; background: var(--red); box-shadow: 0 0 8px rgba(255, 36, 56, 0.5); transform: skewX(-16deg); }
.kf-bars i:nth-child(2) { height: 7px; align-self: center; opacity: 0.7; }
.kf-bars i:nth-child(3) { height: 4px; align-self: center; opacity: 0.4; }
.start-top-right span { color: var(--red); margin: 0 6px; }

.title-block { position: relative; z-index: 2; max-width: 720px; }
.eyebrow { display: flex; align-items: center; gap: 12px; font-family: var(--display); font-size: clamp(6.5px, 0.72vw, 9px); letter-spacing: 0.32em; color: #a4adc0; margin-bottom: 14px; }
.eyebrow .line { width: clamp(18px, 4vw, 52px); height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 36, 56, 0.8)); }
.eyebrow .line:last-child { background: linear-gradient(90deg, rgba(255, 36, 56, 0.8), transparent); }

